window.TL={"duration": 761.994, "cues": [{"id": "lead", "start": 0.0, "end": 2.0}, {"id": "c1", "start": 2.0, "end": 11.158, "text": "El siete de junio de mil novecientos noventa y nueve, un laboratorio de Estados Unidos anunció que había creado algo que nunca había existido en la Tierra.", "words": [{"w": "El", "s": 2.085, "e": 2.34}, {"w": "siete", "s": 2.255, "e": 2.34}, {"w": "de", "s": 2.34, "e": 2.5}, {"w": "junio", "s": 2.5, "e": 2.82}, {"w": "de", "s": 2.82, "e": 2.94}, {"w": "mil", "s": 3.172, "e": 3.472}, {"w": "novecientos", "s": 3.636, "e": 3.936}, {"w": "noventa", "s": 4.1, "e": 4.4}, {"w": "y", "s": 4.564, "e": 4.864}, {"w": "nueve,", "s": 5.028, "e": 5.26}, {"w": "un", "s": 5.26, "e": 5.52}, {"w": "laboratorio", "s": 5.52, "e": 6.1}, {"w": "de", "s": 6.1, "e": 6.26}, {"w": "Estados", "s": 6.26, "e": 6.5}, {"w": "Unidos", "s": 6.5, "e": 7.0}, {"w": "anunció", "s": 7.0, "e": 7.68}, {"w": "que", "s": 7.68, "e": 7.88}, {"w": "había", "s": 7.88, "e": 8.14}, {"w": "creado", "s": 8.14, "e": 8.54}, {"w": "algo", "s": 8.54, "e": 8.86}, {"w": "que", "s": 8.86, "e": 9.22}, {"w": "nunca", "s": 9.22, "e": 9.5}, {"w": "había", "s": 9.5, "e": 9.86}, {"w": "existido", "s": 9.86, "e": 10.46}, {"w": "en", "s": 10.46, "e": 10.58}, {"w": "la", "s": 10.58, "e": 10.68}, {"w": "Tierra.", "s": 10.68, "e": 11.06}]}, {"id": "c2", "start": 11.578, "end": 13.597, "text": "Dos elementos químicos nuevos.", "words": [{"w": "Dos", "s": 11.52, "e": 11.76}, {"w": "elementos", "s": 11.76, "e": 12.14}, {"w": "químicos", "s": 12.14, "e": 12.98}, {"w": "nuevos.", "s": 12.98, "e": 13.26}]}, {"id": "c3", "start": 14.017, "end": 16.683, "text": "El ciento dieciséis, y el ciento dieciocho.", "words": [{"w": "El", "s": 13.98, "e": 14.16}, {"w": "ciento", "s": 14.385, "e": 14.685}, {"w": "dieciséis,", "s": 14.835, "e": 15.06}, {"w": "y", "s": 15.06, "e": 15.44}, {"w": "el", "s": 15.44, "e": 15.58}, {"w": "ciento", "s": 15.856, "e": 16.156}, {"w": "dieciocho.", "s": 16.407, "e": 16.683}]}, {"id": "c4", "start": 17.633, "end": 24.049, "text": "Los había fabricado chocando átomos a una velocidad enorme, en un acelerador de partículas en California.", "words": [{"w": "Los", "s": 17.706, "e": 17.78}, {"w": "había", "s": 17.78, "e": 18.1}, {"w": "fabricado", "s": 18.1, "e": 18.68}, {"w": "chocando", "s": 18.68, "e": 19.22}, {"w": "átomos", "s": 19.22, "e": 19.66}, {"w": "a", "s": 19.66, "e": 19.96}, {"w": "una", "s": 19.96, "e": 20.08}, {"w": "velocidad", "s": 20.08, "e": 20.54}, {"w": "enorme,", "s": 20.54, "e": 21.22}, {"w": "en", "s": 21.62, "e": 21.76}, {"w": "un", "s": 21.76, "e": 21.88}, {"w": "acelerador", "s": 21.88, "e": 22.38}, {"w": "de", "s": 22.38, "e": 22.54}, {"w": "partículas", "s": 22.54, "e": 23.2}, {"w": "en", "s": 23.2, "e": 23.36}, {"w": "California.", "s": 23.36, "e": 23.76}]}, {"id": "c5", "start": 24.469, "end": 26.933, "text": "Las revistas de ciencia lo celebraron.", "words": [{"w": "Las", "s": 24.42, "e": 24.62}, {"w": "revistas", "s": 24.62, "e": 25.1}, {"w": "de", "s": 25.1, "e": 25.38}, {"w": "ciencia", "s": 25.38, "e": 25.92}, {"w": "lo", "s": 26.06, "e": 26.2}, {"w": "celebraron.", "s": 26.2, "e": 26.8}]}, {"id": "c6", "start": 27.353, "end": 30.279, "text": "Los libros de texto se preparaban para cambiar.", "words": [{"w": "Los", "s": 27.34, "e": 27.52}, {"w": "libros", "s": 27.52, "e": 27.92}, {"w": "de", "s": 27.92, "e": 28.04}, {"w": "texto", "s": 28.04, "e": 28.4}, {"w": "se", "s": 28.4, "e": 28.84}, {"w": "preparaban", "s": 28.84, "e": 29.44}, {"w": "para", "s": 29.44, "e": 29.66}, {"w": "cambiar.", "s": 29.66, "e": 30.08}]}, {"id": "c7", "start": 31.229, "end": 38.326, "text": "El primer autor del trabajo era un físico de casi cuarenta años, uno de los mejores cazadores de elementos del mundo.", "words": [{"w": "El", "s": 31.0, "e": 31.34}, {"w": "primer", "s": 31.34, "e": 31.62}, {"w": "autor", "s": 31.62, "e": 31.94}, {"w": "del", "s": 31.94, "e": 32.18}, {"w": "trabajo", "s": 32.18, "e": 32.64}, {"w": "era", "s": 32.64, "e": 33.04}, {"w": "un", "s": 33.04, "e": 33.24}, {"w": "físico", "s": 33.24, "e": 33.68}, {"w": "de", "s": 33.68, "e": 33.78}, {"w": "casi", "s": 33.78, "e": 34.08}, {"w": "cuarenta", "s": 34.3, "e": 34.52}, {"w": "años,", "s": 34.52, "e": 35.1}, {"w": "uno", "s": 35.64, "e": 35.8}, {"w": "de", "s": 35.8, "e": 35.92}, {"w": "los", "s": 35.92, "e": 36.04}, {"w": "mejores", "s": 36.04, "e": 36.42}, {"w": "cazadores", "s": 36.42, "e": 37.0}, {"w": "de", "s": 37.0, "e": 37.26}, {"w": "elementos", "s": 37.26, "e": 37.62}, {"w": "del", "s": 37.62, "e": 37.92}, {"w": "mundo.", "s": 37.92, "e": 38.22}]}, {"id": "c8", "start": 38.746, "end": 40.487, "text": "Se llamaba Victor Ninov.", "words": [{"w": "Se", "s": 38.7, "e": 38.9}, {"w": "llamaba", "s": 38.9, "e": 39.36}, {"w": "Victor", "s": 39.36, "e": 39.74}, {"w": "Ninov.", "s": 40.113, "e": 40.413}]}, {"id": "c9", "start": 42.387, "end": 49.574, "text": "Dos años después, el mismo laboratorio tuvo que admitir algo que nunca le había pasado a ningún laboratorio de su tipo.", "words": [{"w": "Dos", "s": 42.1, "e": 42.58}, {"w": "años", "s": 42.58, "e": 42.84}, {"w": "después,", "s": 42.84, "e": 43.3}, {"w": "el", "s": 43.78, "e": 43.88}, {"w": "mismo", "s": 43.88, "e": 44.16}, {"w": "laboratorio", "s": 44.16, "e": 44.78}, {"w": "tuvo", "s": 44.78, "e": 45.12}, {"w": "que", "s": 45.12, "e": 45.3}, {"w": "admitir", "s": 45.3, "e": 45.78}, {"w": "algo", "s": 45.78, "e": 46.08}, {"w": "que", "s": 46.08, "e": 46.46}, {"w": "nunca", "s": 46.46, "e": 46.72}, {"w": "le", "s": 46.72, "e": 46.94}, {"w": "había", "s": 46.94, "e": 47.2}, {"w": "pasado", "s": 47.2, "e": 47.66}, {"w": "a", "s": 47.66, "e": 47.92}, {"w": "ningún", "s": 47.92, "e": 48.24}, {"w": "laboratorio", "s": 48.24, "e": 48.92}, {"w": "de", "s": 48.92, "e": 49.06}, {"w": "su", "s": 49.06, "e": 49.2}, {"w": "tipo.", "s": 49.2, "e": 49.48}]}, {"id": "c10", "start": 49.994, "end": 52.387, "text": "Esos átomos no existieron nunca.", "words": [{"w": "Esos", "s": 49.96, "e": 50.28}, {"w": "átomos", "s": 50.28, "e": 50.68}, {"w": "no", "s": 50.68, "e": 51.14}, {"w": "existieron", "s": 51.14, "e": 51.78}, {"w": "nunca.", "s": 51.78, "e": 52.22}]}, {"id": "c11", "start": 52.807, "end": 57.992, "text": "Y cuando revisaron los datos originales, descubrieron que la prueba tampoco estaba ahí.", "words": [{"w": "Y", "s": 52.62, "e": 52.92}, {"w": "cuando", "s": 52.92, "e": 53.08}, {"w": "revisaron", "s": 53.08, "e": 53.76}, {"w": "los", "s": 53.76, "e": 53.96}, {"w": "datos", "s": 53.96, "e": 54.24}, {"w": "originales,", "s": 54.24, "e": 55.14}, {"w": "descubrieron", "s": 55.42, "e": 56.08}, {"w": "que", "s": 56.08, "e": 56.22}, {"w": "la", "s": 56.22, "e": 56.34}, {"w": "prueba", "s": 56.34, "e": 56.64}, {"w": "tampoco", "s": 56.64, "e": 56.86}, {"w": "estaba", "s": 56.86, "e": 57.58}, {"w": "ahí.", "s": 57.58, "e": 57.94}]}, {"id": "c12", "start": 58.942, "end": 65.131, "text": "Esta es la historia de cómo un científico brillante intentó agregar dos casillas a la tabla periódica.", "words": [{"w": "Esta", "s": 58.8, "e": 59.16}, {"w": "es", "s": 59.16, "e": 59.3}, {"w": "la", "s": 59.3, "e": 59.42}, {"w": "historia", "s": 59.42, "e": 59.74}, {"w": "de", "s": 59.74, "e": 59.94}, {"w": "cómo", "s": 59.94, "e": 60.12}, {"w": "un", "s": 60.12, "e": 60.3}, {"w": "científico", "s": 60.3, "e": 60.96}, {"w": "brillante", "s": 60.96, "e": 61.56}, {"w": "intentó", "s": 61.56, "e": 62.46}, {"w": "agregar", "s": 62.46, "e": 62.92}, {"w": "dos", "s": 62.92, "e": 63.2}, {"w": "casillas", "s": 63.2, "e": 63.78}, {"w": "a", "s": 63.78, "e": 64.02}, {"w": "la", "s": 64.02, "e": 64.12}, {"w": "tabla", "s": 64.12, "e": 64.42}, {"w": "periódica.", "s": 64.42, "e": 65.06}]}, {"id": "c13", "start": 65.551, "end": 66.983, "text": "Y de por qué no pudo.", "words": [{"w": "Y", "s": 65.46, "e": 65.7}, {"w": "de", "s": 65.7, "e": 65.84}, {"w": "por", "s": 65.84, "e": 66.0}, {"w": "qué", "s": 66.0, "e": 66.26}, {"w": "no", "s": 66.26, "e": 66.42}, {"w": "pudo.", "s": 66.42, "e": 66.8}]}, {"id": "titulo", "start": 68.883, "end": 74.383}, {"id": "cap1", "start": 74.383, "end": 78.383}, {"id": "c14", "start": 78.383, "end": 81.186, "text": "En la naturaleza hay unos noventa elementos.", "words": [{"w": "En", "s": 78.431, "e": 78.48}, {"w": "la", "s": 78.48, "e": 78.6}, {"w": "naturaleza", "s": 78.6, "e": 79.28}, {"w": "hay", "s": 79.28, "e": 79.58}, {"w": "unos", "s": 79.58, "e": 79.9}, {"w": "noventa", "s": 80.16, "e": 80.42}, {"w": "elementos.", "s": 80.42, "e": 80.94}]}, {"id": "c15", "start": 81.606, "end": 87.386, "text": "Del hidrógeno, el más liviano, al uranio, el más pesado que se encuentra en cantidad en la Tierra.", "words": [{"w": "Del", "s": 81.54, "e": 81.74}, {"w": "hidrógeno,", "s": 81.74, "e": 82.48}, {"w": "el", "s": 82.62, "e": 82.64}, {"w": "más", "s": 82.64, "e": 82.84}, {"w": "liviano,", "s": 82.84, "e": 83.36}, {"w": "al", "s": 83.545, "e": 83.845}, {"w": "uranio,", "s": 83.915, "e": 84.1}, {"w": "el", "s": 84.1, "e": 84.56}, {"w": "más", "s": 84.56, "e": 84.76}, {"w": "pesado", "s": 84.76, "e": 85.2}, {"w": "que", "s": 85.2, "e": 85.38}, {"w": "se", "s": 85.38, "e": 85.56}, {"w": "encuentra", "s": 85.56, "e": 85.96}, {"w": "en", "s": 85.96, "e": 86.16}, {"w": "cantidad", "s": 86.16, "e": 86.58}, {"w": "en", "s": 86.58, "e": 86.8}, {"w": "la", "s": 86.8, "e": 86.9}, {"w": "Tierra.", "s": 86.9, "e": 87.28}]}, {"id": "c16", "start": 87.806, "end": 91.054, "text": "Todo lo que está después del uranio hubo que fabricarlo.", "words": [{"w": "Todo", "s": 87.78, "e": 87.98}, {"w": "lo", "s": 87.98, "e": 88.2}, {"w": "que", "s": 88.2, "e": 88.34}, {"w": "está", "s": 88.34, "e": 88.54}, {"w": "después", "s": 88.54, "e": 89.02}, {"w": "del", "s": 89.02, "e": 89.28}, {"w": "uranio", "s": 89.28, "e": 89.76}, {"w": "hubo", "s": 89.76, "e": 90.16}, {"w": "que", "s": 90.16, "e": 90.32}, {"w": "fabricarlo.", "s": 90.32, "e": 90.94}]}, {"id": "c17", "start": 92.004, "end": 95.293, "text": "La receta es simple de explicar, y muy difícil de hacer.", "words": [{"w": "La", "s": 91.82, "e": 92.12}, {"w": "receta", "s": 92.12, "e": 92.52}, {"w": "es", "s": 92.52, "e": 92.66}, {"w": "simple", "s": 92.66, "e": 92.96}, {"w": "de", "s": 92.96, "e": 93.1}, {"w": "explicar,", "s": 93.1, "e": 93.58}, {"w": "y", "s": 93.58, "e": 94.0}, {"w": "muy", "s": 94.0, "e": 94.2}, {"w": "difícil", "s": 94.2, "e": 94.68}, {"w": "de", "s": 94.68, "e": 94.9}, {"w": "hacer.", "s": 94.9, "e": 95.18}]}, {"id": "c18", "start": 95.713, "end": 105.139, "text": "Se toma un átomo pesado, se le dispara otro átomo a una velocidad enorme, y se espera que, en algún choque entre billones, los dos núcleos se fundan en uno solo.", "words": [{"w": "Se", "s": 95.68, "e": 95.84}, {"w": "toma", "s": 95.84, "e": 96.06}, {"w": "un", "s": 96.06, "e": 96.24}, {"w": "átomo", "s": 96.24, "e": 96.46}, {"w": "pesado,", "s": 96.46, "e": 96.98}, {"w": "se", "s": 97.32, "e": 97.38}, {"w": "le", "s": 97.38, "e": 97.48}, {"w": "dispara", "s": 97.48, "e": 97.92}, {"w": "otro", "s": 97.92, "e": 98.14}, {"w": "átomo", "s": 98.14, "e": 98.6}, {"w": "a", "s": 98.6, "e": 98.74}, {"w": "una", "s": 98.74, "e": 98.86}, {"w": "velocidad", "s": 98.86, "e": 99.26}, {"w": "enorme,", "s": 99.26, "e": 99.9}, {"w": "y", "s": 100.26, "e": 100.44}, {"w": "se", "s": 100.44, "e": 100.56}, {"w": "espera", "s": 100.56, "e": 100.9}, {"w": "que,", "s": 100.9, "e": 101.12}, {"w": "en", "s": 101.12, "e": 101.32}, {"w": "algún", "s": 101.32, "e": 101.6}, {"w": "choque", "s": 101.6, "e": 101.98}, {"w": "entre", "s": 101.98, "e": 102.2}, {"w": "billones,", "s": 102.2, "e": 102.68}, {"w": "los", "s": 102.68, "e": 103.1}, {"w": "dos", "s": 103.1, "e": 103.32}, {"w": "núcleos", "s": 103.32, "e": 103.82}, {"w": "se", "s": 103.82, "e": 103.98}, {"w": "fundan", "s": 103.98, "e": 104.38}, {"w": "en", "s": 104.38, "e": 104.56}, {"w": "uno", "s": 104.56, "e": 104.7}, {"w": "solo.", "s": 104.7, "e": 105.06}]}, {"id": "c19", "start": 106.089, "end": 108.831, "text": "Si se funden, el número de protones se suma.", "words": [{"w": "Si", "s": 105.92, "e": 106.22}, {"w": "se", "s": 106.22, "e": 106.36}, {"w": "funden,", "s": 106.36, "e": 106.82}, {"w": "el", "s": 107.02, "e": 107.14}, {"w": "número", "s": 107.14, "e": 107.4}, {"w": "de", "s": 107.4, "e": 107.66}, {"w": "protones", "s": 107.66, "e": 108.12}, {"w": "se", "s": 108.12, "e": 108.34}, {"w": "suma.", "s": 108.34, "e": 108.78}]}, {"id": "c20", "start": 109.251, "end": 112.434, "text": "Y el número de protones es lo que define a un elemento.", "words": [{"w": "Y", "s": 109.14, "e": 109.36}, {"w": "el", "s": 109.36, "e": 109.46}, {"w": "número", "s": 109.46, "e": 109.72}, {"w": "de", "s": 109.72, "e": 109.9}, {"w": "protones", "s": 109.9, "e": 110.38}, {"w": "es", "s": 110.38, "e": 110.84}, {"w": "lo", "s": 110.84, "e": 110.98}, {"w": "que", "s": 110.98, "e": 111.12}, {"w": "define", "s": 111.12, "e": 111.58}, {"w": "a", "s": 111.58, "e": 111.72}, {"w": "un", "s": 111.72, "e": 111.86}, {"w": "elemento.", "s": 111.86, "e": 112.22}]}, {"id": "c21", "start": 113.384, "end": 116.095, "text": "Pero estos núcleos gigantes son inestables.", "words": [{"w": "Pero", "s": 113.442, "e": 113.5}, {"w": "estos", "s": 113.5, "e": 113.82}, {"w": "núcleos", "s": 113.82, "e": 114.4}, {"w": "gigantes", "s": 114.4, "e": 114.92}, {"w": "son", "s": 114.92, "e": 115.28}, {"w": "inestables.", "s": 115.28, "e": 115.9}]}, {"id": "c22", "start": 116.515, "end": 119.163, "text": "Viven milésimas de segundo, y se desarman.", "words": [{"w": "Viven", "s": 116.5, "e": 116.84}, {"w": "milésimas", "s": 116.84, "e": 117.38}, {"w": "de", "s": 117.38, "e": 117.58}, {"w": "segundo,", "s": 117.58, "e": 118.02}, {"w": "y", "s": 118.02, "e": 118.38}, {"w": "se", "s": 118.38, "e": 118.54}, {"w": "desarman.", "s": 118.54, "e": 119.12}]}, {"id": "c23", "start": 119.583, "end": 124.736, "text": "Cada vez que pierden un pedazo, una partícula alfa, bajan dos casillas en la tabla.", "words": [{"w": "Cada", "s": 119.52, "e": 119.74}, {"w": "vez", "s": 119.74, "e": 120.0}, {"w": "que", "s": 120.0, "e": 120.2}, {"w": "pierden", "s": 120.2, "e": 120.54}, {"w": "un", "s": 120.54, "e": 120.7}, {"w": "pedazo,", "s": 120.7, "e": 121.14}, {"w": "una", "s": 121.38, "e": 121.52}, {"w": "partícula", "s": 121.52, "e": 122.1}, {"w": "alfa,", "s": 122.1, "e": 122.46}, {"w": "bajan", "s": 122.46, "e": 123.14}, {"w": "dos", "s": 123.14, "e": 123.36}, {"w": "casillas", "s": 123.36, "e": 123.88}, {"w": "en", "s": 123.88, "e": 124.14}, {"w": "la", "s": 124.14, "e": 124.26}, {"w": "tabla.", "s": 124.26, "e": 124.66}]}, {"id": "c24", "start": 125.686, "end": 130.412, "text": "Esa escalera de caídas, una detrás de otra, es la huella digital del elemento.", "words": [{"w": "Esa", "s": 125.64, "e": 125.9}, {"w": "escalera", "s": 125.9, "e": 126.34}, {"w": "de", "s": 126.34, "e": 126.48}, {"w": "caídas,", "s": 126.48, "e": 127.04}, {"w": "una", "s": 127.2, "e": 127.32}, {"w": "detrás", "s": 127.32, "e": 127.72}, {"w": "de", "s": 127.72, "e": 127.86}, {"w": "otra,", "s": 127.86, "e": 128.1}, {"w": "es", "s": 128.46, "e": 128.64}, {"w": "la", "s": 128.64, "e": 128.78}, {"w": "huella", "s": 128.78, "e": 129.08}, {"w": "digital", "s": 129.08, "e": 129.6}, {"w": "del", "s": 129.6, "e": 129.8}, {"w": "elemento.", "s": 129.8, "e": 130.08}]}, {"id": "c25", "start": 130.832, "end": 132.238, "text": "Nadie ve el átomo.", "words": [{"w": "Nadie", "s": 130.78, "e": 131.22}, {"w": "ve", "s": 131.22, "e": 131.48}, {"w": "el", "s": 131.48, "e": 131.66}, {"w": "átomo.", "s": 131.66, "e": 132.06}]}, {"id": "c26", "start": 132.658, "end": 139.179, "text": "Lo que se ve es la cadena de desintegraciones que deja en un detector, con su posición y su tiempo exactos.", "words": [{"w": "Lo", "s": 132.62, "e": 132.78}, {"w": "que", "s": 132.78, "e": 132.92}, {"w": "se", "s": 132.92, "e": 133.1}, {"w": "ve", "s": 133.1, "e": 133.3}, {"w": "es", "s": 133.3, "e": 133.54}, {"w": "la", "s": 133.54, "e": 133.68}, {"w": "cadena", "s": 133.68, "e": 134.06}, {"w": "de", "s": 134.06, "e": 134.22}, {"w": "desintegraciones", "s": 134.22, "e": 135.02}, {"w": "que", "s": 135.02, "e": 135.32}, {"w": "deja", "s": 135.32, "e": 135.64}, {"w": "en", "s": 135.64, "e": 135.78}, {"w": "un", "s": 135.78, "e": 135.88}, {"w": "detector,", "s": 135.88, "e": 136.36}, {"w": "con", "s": 136.76, "e": 136.98}, {"w": "su", "s": 136.98, "e": 137.16}, {"w": "posición", "s": 137.16, "e": 137.66}, {"w": "y", "s": 137.66, "e": 138.04}, {"w": "su", "s": 138.04, "e": 138.2}, {"w": "tiempo", "s": 138.2, "e": 138.48}, {"w": "exactos.", "s": 138.829, "e": 139.129}]}, {"id": "c27", "start": 141.079, "end": 145.919, "text": "Durante el siglo veinte, la caza de elementos fue una carrera entre tres lugares.", "words": [{"w": "Durante", "s": 141.269, "e": 141.46}, {"w": "el", "s": 141.46, "e": 141.64}, {"w": "siglo", "s": 141.64, "e": 141.94}, {"w": "veinte,", "s": 142.37, "e": 142.67}, {"w": "la", "s": 142.8, "e": 142.88}, {"w": "caza", "s": 143.03, "e": 143.18}, {"w": "de", "s": 143.18, "e": 143.34}, {"w": "elementos", "s": 143.34, "e": 143.72}, {"w": "fue", "s": 143.72, "e": 144.12}, {"w": "una", "s": 144.12, "e": 144.3}, {"w": "carrera", "s": 144.3, "e": 144.72}, {"w": "entre", "s": 144.72, "e": 144.94}, {"w": "tres", "s": 144.94, "e": 145.28}, {"w": "lugares.", "s": 145.28, "e": 145.72}]}, {"id": "c28", "start": 146.339, "end": 147.928, "text": "Berkeley, en California.", "words": [{"w": "Berkeley,", "s": 146.3, "e": 146.74}, {"w": "en", "s": 146.74, "e": 147.04}, {"w": "California.", "s": 147.04, "e": 147.66}]}, {"id": "c29", "start": 148.348, "end": 150.237, "text": "Dubna, en la Unión Soviética.", "words": [{"w": "Dubna,", "s": 148.28, "e": 148.72}, {"w": "en", "s": 148.72, "e": 148.96}, {"w": "la", "s": 148.96, "e": 149.06}, {"w": "Unión", "s": 149.06, "e": 149.32}, {"w": "Soviética.", "s": 149.32, "e": 150.08}]}, {"id": "c30", "start": 150.657, "end": 155.765, "text": "Y Darmstadt, en Alemania, donde funciona un centro de investigación llamado GSI.", "words": [{"w": "Y", "s": 150.62, "e": 150.76}, {"w": "Darmstadt,", "s": 150.76, "e": 151.22}, {"w": "en", "s": 151.22, "e": 151.54}, {"w": "Alemania,", "s": 151.54, "e": 152.02}, {"w": "donde", "s": 152.42, "e": 152.54}, {"w": "funciona", "s": 152.54, "e": 153.08}, {"w": "un", "s": 153.08, "e": 153.3}, {"w": "centro", "s": 153.3, "e": 153.6}, {"w": "de", "s": 153.6, "e": 153.78}, {"w": "investigación", "s": 153.78, "e": 154.36}, {"w": "llamado", "s": 154.36, "e": 155.0}, {"w": "GSI.", "s": 155.0, "e": 155.62}]}, {"id": "c31", "start": 156.715, "end": 166.081, "text": "En GSI, entre mil novecientos noventa y cuatro y mil novecientos noventa y seis, un equipo creó los elementos ciento diez, ciento once y ciento doce.", "words": [{"w": "En", "s": 156.44, "e": 156.84}, {"w": "GSI,", "s": 156.84, "e": 157.34}, {"w": "entre", "s": 157.56, "e": 157.72}, {"w": "mil", "s": 157.873, "e": 158.173}, {"w": "novecientos", "s": 158.18, "e": 158.48}, {"w": "noventa", "s": 158.487, "e": 158.64}, {"w": "y", "s": 158.64, "e": 159.66}, {"w": "cuatro", "s": 159.817, "e": 160.117}, {"w": "y", "s": 160.131, "e": 160.431}, {"w": "mil", "s": 160.446, "e": 160.746}, {"w": "novecientos", "s": 160.76, "e": 161.06}, {"w": "noventa", "s": 161.074, "e": 161.374}, {"w": "y", "s": 161.389, "e": 161.689}, {"w": "seis,", "s": 161.703, "e": 161.86}, {"w": "un", "s": 161.86, "e": 161.96}, {"w": "equipo", "s": 161.96, "e": 162.2}, {"w": "creó", "s": 162.2, "e": 162.58}, {"w": "los", "s": 162.58, "e": 162.74}, {"w": "elementos", "s": 162.74, "e": 163.14}, {"w": "ciento", "s": 163.355, "e": 163.655}, {"w": "diez,", "s": 163.785, "e": 164.085}, {"w": "ciento", "s": 164.215, "e": 164.515}, {"w": "once", "s": 164.645, "e": 164.86}, {"w": "y", "s": 164.86, "e": 165.28}, {"w": "ciento", "s": 165.48, "e": 165.78}, {"w": "doce.", "s": 165.881, "e": 166.081}]}, {"id": "c32", "start": 167.031, "end": 169.819, "text": "En ese equipo había un joven físico búlgaro.", "words": [{"w": "En", "s": 167.085, "e": 167.14}, {"w": "ese", "s": 167.14, "e": 167.36}, {"w": "equipo", "s": 167.36, "e": 167.7}, {"w": "había", "s": 167.7, "e": 168.1}, {"w": "un", "s": 168.1, "e": 168.38}, {"w": "joven", "s": 168.38, "e": 168.7}, {"w": "físico", "s": 168.7, "e": 169.2}, {"w": "búlgaro.", "s": 169.2, "e": 170.1}]}, {"id": "c33", "start": 170.239, "end": 179.515, "text": "Su especialidad era un aparato llamado separador de gas: un filtro que, de todo lo que sale de un choque, deja pasar solo a los átomos pesados que interesan.", "words": [{"w": "Su", "s": 170.18, "e": 170.36}, {"w": "especialidad", "s": 170.36, "e": 171.04}, {"w": "era", "s": 171.04, "e": 171.38}, {"w": "un", "s": 171.38, "e": 171.56}, {"w": "aparato", "s": 171.56, "e": 171.96}, {"w": "llamado", "s": 171.96, "e": 172.26}, {"w": "separador", "s": 172.26, "e": 172.92}, {"w": "de", "s": 172.92, "e": 173.08}, {"w": "gas:", "s": 173.08, "e": 173.32}, {"w": "un", "s": 173.82, "e": 173.98}, {"w": "filtro", "s": 173.98, "e": 174.38}, {"w": "que,", "s": 174.38, "e": 174.6}, {"w": "de", "s": 174.74, "e": 174.82}, {"w": "todo", "s": 174.82, "e": 175.0}, {"w": "lo", "s": 175.0, "e": 175.18}, {"w": "que", "s": 175.18, "e": 175.32}, {"w": "sale", "s": 175.32, "e": 175.56}, {"w": "de", "s": 175.56, "e": 175.72}, {"w": "un", "s": 175.72, "e": 175.84}, {"w": "choque,", "s": 175.84, "e": 176.22}, {"w": "deja", "s": 176.58, "e": 176.78}, {"w": "pasar", "s": 176.78, "e": 177.1}, {"w": "solo", "s": 177.1, "e": 177.54}, {"w": "a", "s": 177.54, "e": 177.68}, {"w": "los", "s": 177.68, "e": 177.82}, {"w": "átomos", "s": 177.82, "e": 178.08}, {"w": "pesados", "s": 178.08, "e": 178.64}, {"w": "que", "s": 178.64, "e": 178.86}, {"w": "interesan.", "s": 178.86, "e": 179.48}]}, {"id": "c34", "start": 179.935, "end": 181.277, "text": "Era Victor Ninov.", "words": [{"w": "Era", "s": 179.9, "e": 180.16}, {"w": "Victor", "s": 180.16, "e": 180.54}, {"w": "Ninov.", "s": 180.54, "e": 181.16}]}, {"id": "c35", "start": 182.227, "end": 188.052, "text": "Además de saber construir el filtro, Ninov dominaba el programa con el que se analizaban los datos.", "words": [{"w": "Además", "s": 182.14, "e": 182.44}, {"w": "de", "s": 182.44, "e": 182.68}, {"w": "saber", "s": 182.68, "e": 182.98}, {"w": "construir", "s": 182.98, "e": 183.48}, {"w": "el", "s": 183.48, "e": 183.72}, {"w": "filtro,", "s": 183.72, "e": 184.18}, {"w": "Ninov", "s": 184.7, "e": 184.96}, {"w": "dominaba", "s": 184.96, "e": 185.42}, {"w": "el", "s": 185.42, "e": 185.56}, {"w": "programa", "s": 185.56, "e": 185.96}, {"w": "con", "s": 185.96, "e": 186.34}, {"w": "el", "s": 186.34, "e": 186.46}, {"w": "que", "s": 186.46, "e": 186.56}, {"w": "se", "s": 186.56, "e": 186.72}, {"w": "analizaban", "s": 186.72, "e": 187.28}, {"w": "los", "s": 187.28, "e": 187.5}, {"w": "datos.", "s": 187.5, "e": 187.82}]}, {"id": "c36", "start": 188.472, "end": 191.693, "text": "Un programa complicado, que muy pocos sabían usar.", "words": [{"w": "Un", "s": 188.42, "e": 188.62}, {"w": "programa", "s": 188.62, "e": 189.0}, {"w": "complicado,", "s": 189.0, "e": 189.62}, {"w": "que", "s": 189.62, "e": 190.08}, {"w": "muy", "s": 190.08, "e": 190.26}, {"w": "pocos", "s": 190.26, "e": 190.7}, {"w": "sabían", "s": 190.7, "e": 191.14}, {"w": "usar.", "s": 191.14, "e": 191.56}]}, {"id": "c37", "start": 192.643, "end": 197.259, "text": "A mediados de los noventa, el Laboratorio Nacional Lawrence Berkeley lo contrató.", "words": [{"w": "A", "s": 192.44, "e": 192.74}, {"w": "mediados", "s": 192.74, "e": 193.1}, {"w": "de", "s": 193.1, "e": 193.22}, {"w": "los", "s": 193.22, "e": 193.36}, {"w": "noventa,", "s": 193.79, "e": 194.09}, {"w": "el", "s": 194.22, "e": 194.38}, {"w": "Laboratorio", "s": 194.38, "e": 194.92}, {"w": "Nacional", "s": 194.92, "e": 195.44}, {"w": "Lawrence", "s": 195.44, "e": 195.88}, {"w": "Berkeley", "s": 195.88, "e": 196.48}, {"w": "lo", "s": 196.48, "e": 196.68}, {"w": "contrató.", "s": 196.68, "e": 197.22}]}, {"id": "c38", "start": 197.679, "end": 200.724, "text": "Berkeley quería volver a la carrera de los elementos.", "words": [{"w": "Berkeley", "s": 197.66, "e": 198.0}, {"w": "quería", "s": 198.0, "e": 198.46}, {"w": "volver", "s": 198.46, "e": 198.8}, {"w": "a", "s": 198.8, "e": 199.24}, {"w": "la", "s": 199.24, "e": 199.32}, {"w": "carrera", "s": 199.32, "e": 199.74}, {"w": "de", "s": 199.74, "e": 199.88}, {"w": "los", "s": 199.88, "e": 200.04}, {"w": "elementos.", "s": 200.04, "e": 200.48}]}, {"id": "c39", "start": 201.144, "end": 203.991, "text": "Y Ninov era exactamente lo que necesitaba.", "words": [{"w": "Y", "s": 201.02, "e": 201.26}, {"w": "Ninov", "s": 201.26, "e": 201.68}, {"w": "era", "s": 201.68, "e": 201.94}, {"w": "exactamente", "s": 201.94, "e": 202.6}, {"w": "lo", "s": 202.6, "e": 202.98}, {"w": "que", "s": 202.98, "e": 203.14}, {"w": "necesitaba.", "s": 203.14, "e": 203.88}]}, {"id": "cap2", "start": 204.941, "end": 208.941}, {"id": "c40", "start": 208.941, "end": 213.684, "text": "Para fabricar elementos cada vez más pesados, los físicos tenían un problema.", "words": [{"w": "Para", "s": 209.01, "e": 209.08}, {"w": "fabricar", "s": 209.08, "e": 209.58}, {"w": "elementos", "s": 209.58, "e": 210.12}, {"w": "cada", "s": 210.12, "e": 210.38}, {"w": "vez", "s": 210.38, "e": 210.7}, {"w": "más", "s": 210.7, "e": 210.92}, {"w": "pesados,", "s": 210.92, "e": 211.46}, {"w": "los", "s": 211.86, "e": 212.02}, {"w": "físicos", "s": 212.02, "e": 212.44}, {"w": "tenían", "s": 212.44, "e": 212.84}, {"w": "un", "s": 212.84, "e": 213.08}, {"w": "problema.", "s": 213.08, "e": 213.52}]}, {"id": "c41", "start": 214.104, "end": 218.025, "text": "Cuanto más arriba en la tabla, menos probable es que el choque funcione.", "words": [{"w": "Cuanto", "s": 214.08, "e": 214.32}, {"w": "más", "s": 214.32, "e": 214.58}, {"w": "arriba", "s": 214.58, "e": 214.9}, {"w": "en", "s": 214.9, "e": 215.04}, {"w": "la", "s": 215.04, "e": 215.14}, {"w": "tabla,", "s": 215.14, "e": 215.52}, {"w": "menos", "s": 215.9, "e": 216.02}, {"w": "probable", "s": 216.02, "e": 216.48}, {"w": "es", "s": 216.48, "e": 216.82}, {"w": "que", "s": 216.82, "e": 216.92}, {"w": "el", "s": 216.92, "e": 217.04}, {"w": "choque", "s": 217.04, "e": 217.32}, {"w": "funcione.", "s": 217.32, "e": 217.92}]}, {"id": "c42", "start": 218.445, "end": 226.236, "text": "Para los últimos elementos que se habían descubierto, hacían falta semanas de choques continuos para conseguir uno o dos átomos.", "words": [{"w": "Para", "s": 218.38, "e": 218.58}, {"w": "los", "s": 218.58, "e": 218.76}, {"w": "últimos", "s": 218.76, "e": 219.1}, {"w": "elementos", "s": 219.1, "e": 219.62}, {"w": "que", "s": 219.62, "e": 219.94}, {"w": "se", "s": 219.94, "e": 220.1}, {"w": "habían", "s": 220.1, "e": 220.38}, {"w": "descubierto,", "s": 220.38, "e": 221.12}, {"w": "hacían", "s": 221.52, "e": 221.96}, {"w": "falta", "s": 221.96, "e": 222.3}, {"w": "semanas", "s": 222.3, "e": 222.76}, {"w": "de", "s": 222.76, "e": 223.0}, {"w": "choques", "s": 223.0, "e": 223.4}, {"w": "continuos", "s": 223.4, "e": 224.08}, {"w": "para", "s": 224.08, "e": 224.26}, {"w": "conseguir", "s": 224.26, "e": 224.68}, {"w": "uno", "s": 224.68, "e": 225.08}, {"w": "o", "s": 225.08, "e": 225.42}, {"w": "dos", "s": 225.42, "e": 225.64}, {"w": "átomos.", "s": 225.64, "e": 226.04}]}, {"id": "c43", "start": 227.186, "end": 232.827, "text": "Y entonces llegó a Berkeley un teórico polaco, Robert Smolańczuk, con un cálculo sorprendente.", "words": [{"w": "Y", "s": 227.233, "e": 227.28}, {"w": "entonces", "s": 227.28, "e": 227.66}, {"w": "llegó", "s": 227.66, "e": 228.1}, {"w": "a", "s": 228.1, "e": 228.26}, {"w": "Berkeley", "s": 228.365, "e": 228.665}, {"w": "un", "s": 228.575, "e": 228.68}, {"w": "teórico", "s": 228.68, "e": 229.08}, {"w": "polaco,", "s": 229.08, "e": 229.58}, {"w": "Robert", "s": 229.98, "e": 230.22}, {"w": "Smolańczuk,", "s": 230.7, "e": 231.0}, {"w": "con", "s": 231.18, "e": 231.32}, {"w": "un", "s": 231.32, "e": 231.44}, {"w": "cálculo", "s": 231.44, "e": 231.86}, {"w": "sorprendente.", "s": 231.86, "e": 232.72}]}, {"id": "c44", "start": 233.247, "end": 243.113, "text": "Según su cálculo, si se disparaba criptón contra plomo, la probabilidad de crear el elemento ciento dieciocho era mucho más alta de lo que todo el mundo pensaba.", "words": [{"w": "Según", "s": 233.22, "e": 233.52}, {"w": "su", "s": 233.52, "e": 233.7}, {"w": "cálculo,", "s": 233.7, "e": 234.22}, {"w": "si", "s": 234.5, "e": 234.58}, {"w": "se", "s": 234.58, "e": 234.72}, {"w": "disparaba", "s": 234.72, "e": 235.2}, {"w": "criptón", "s": 235.44, "e": 235.68}, {"w": "contra", "s": 235.68, "e": 236.06}, {"w": "plomo,", "s": 236.06, "e": 236.48}, {"w": "la", "s": 236.98, "e": 237.08}, {"w": "probabilidad", "s": 237.08, "e": 237.74}, {"w": "de", "s": 237.74, "e": 237.88}, {"w": "crear", "s": 237.88, "e": 238.18}, {"w": "el", "s": 238.18, "e": 238.34}, {"w": "elemento", "s": 238.34, "e": 238.7}, {"w": "ciento", "s": 238.975, "e": 239.275}, {"w": "dieciocho", "s": 239.525, "e": 239.8}, {"w": "era", "s": 239.8, "e": 240.36}, {"w": "mucho", "s": 240.36, "e": 240.64}, {"w": "más", "s": 240.64, "e": 240.92}, {"w": "alta", "s": 240.92, "e": 241.36}, {"w": "de", "s": 241.36, "e": 241.5}, {"w": "lo", "s": 241.5, "e": 241.6}, {"w": "que", "s": 241.6, "e": 241.74}, {"w": "todo", "s": 241.74, "e": 242.0}, {"w": "el", "s": 242.0, "e": 242.18}, {"w": "mundo", "s": 242.18, "e": 242.38}, {"w": "pensaba.", "s": 242.38, "e": 243.0}]}, {"id": "c45", "start": 244.063, "end": 246.731, "text": "El criptón tiene treinta y seis protones.", "words": [{"w": "El", "s": 243.92, "e": 244.18}, {"w": "criptón", "s": 244.4, "e": 244.62}, {"w": "tiene", "s": 244.62, "e": 244.98}, {"w": "treinta", "s": 245.087, "e": 245.387}, {"w": "y", "s": 245.3, "e": 245.6}, {"w": "seis", "s": 245.513, "e": 245.62}, {"w": "protones.", "s": 245.62, "e": 246.58}]}, {"id": "c46", "start": 247.151, "end": 248.999, "text": "El plomo, ochenta y dos.", "words": [{"w": "El", "s": 247.16, "e": 247.3}, {"w": "plomo,", "s": 247.3, "e": 247.64}, {"w": "ochenta", "s": 247.866, "e": 248.166}, {"w": "y", "s": 248.319, "e": 248.619}, {"w": "dos.", "s": 248.772, "e": 248.999}]}, {"id": "c47", "start": 249.419, "end": 251.157, "text": "Juntos, ciento dieciocho.", "words": [{"w": "Juntos,", "s": 249.34, "e": 249.8}, {"w": "ciento", "s": 250.139, "e": 250.439}, {"w": "dieciocho.", "s": 250.818, "e": 251.118}]}, {"id": "c48", "start": 252.107, "end": 253.74, "text": "Era una idea polémica.", "words": [{"w": "Era", "s": 251.96, "e": 252.3}, {"w": "una", "s": 252.3, "e": 252.6}, {"w": "idea", "s": 252.6, "e": 252.96}, {"w": "polémica.", "s": 252.96, "e": 253.6}]}, {"id": "c49", "start": 254.16, "end": 256.124, "text": "Muchos colegas no la creían.", "words": [{"w": "Muchos", "s": 254.16, "e": 254.54}, {"w": "colegas", "s": 254.54, "e": 255.1}, {"w": "no", "s": 255.1, "e": 255.42}, {"w": "la", "s": 255.42, "e": 255.56}, {"w": "creían.", "s": 255.56, "e": 256.02}]}, {"id": "c50", "start": 256.544, "end": 258.776, "text": "Pero en Berkeley decidieron probarla.", "words": [{"w": "Pero", "s": 256.48, "e": 256.72}, {"w": "en", "s": 256.72, "e": 256.88}, {"w": "Berkeley", "s": 256.88, "e": 257.24}, {"w": "decidieron", "s": 257.24, "e": 258.02}, {"w": "probarla.", "s": 258.02, "e": 258.66}]}, {"id": "c51", "start": 259.196, "end": 265.728, "text": "Tenían un acelerador capaz de producir un haz intenso de criptón, y un separador de gas recién instalado.", "words": [{"w": "Tenían", "s": 259.18, "e": 259.52}, {"w": "un", "s": 259.52, "e": 259.68}, {"w": "acelerador", "s": 259.68, "e": 260.28}, {"w": "capaz", "s": 260.28, "e": 260.6}, {"w": "de", "s": 260.6, "e": 260.84}, {"w": "producir", "s": 260.84, "e": 261.34}, {"w": "un", "s": 261.34, "e": 261.56}, {"w": "haz", "s": 261.63, "e": 261.7}, {"w": "intenso", "s": 261.7, "e": 262.22}, {"w": "de", "s": 262.22, "e": 262.36}, {"w": "criptón,", "s": 262.62, "e": 262.88}, {"w": "y", "s": 262.88, "e": 263.42}, {"w": "un", "s": 263.42, "e": 263.54}, {"w": "separador", "s": 263.54, "e": 264.06}, {"w": "de", "s": 264.06, "e": 264.22}, {"w": "gas", "s": 264.22, "e": 264.48}, {"w": "recién", "s": 264.48, "e": 264.98}, {"w": "instalado.", "s": 264.98, "e": 265.64}]}, {"id": "c52", "start": 266.148, "end": 268.601, "text": "El experto en ese separador era Ninov.", "words": [{"w": "El", "s": 266.14, "e": 266.26}, {"w": "experto", "s": 266.26, "e": 266.8}, {"w": "en", "s": 266.8, "e": 266.94}, {"w": "ese", "s": 266.94, "e": 267.12}, {"w": "separador", "s": 267.12, "e": 267.76}, {"w": "era", "s": 267.76, "e": 268.14}, {"w": "Ninov.", "s": 268.14, "e": 268.6}]}, {"id": "c53", "start": 269.551, "end": 274.056, "text": "En la primavera de mil novecientos noventa y nueve empezó el experimento.", "words": [{"w": "En", "s": 269.605, "e": 269.66}, {"w": "la", "s": 269.66, "e": 269.78}, {"w": "primavera", "s": 269.78, "e": 270.3}, {"w": "de", "s": 270.3, "e": 270.42}, {"w": "mil", "s": 270.52, "e": 270.82}, {"w": "novecientos", "s": 270.72, "e": 271.02}, {"w": "noventa", "s": 270.92, "e": 271.22}, {"w": "y", "s": 271.12, "e": 271.42}, {"w": "nueve", "s": 271.32, "e": 271.42}, {"w": "empezó", "s": 271.42, "e": 273.18}, {"w": "el", "s": 273.18, "e": 273.28}, {"w": "experimento.", "s": 273.28, "e": 274.12}]}, {"id": "c54", "start": 274.476, "end": 281.159, "text": "El acelerador disparaba unos dos billones de átomos de criptón por segundo contra láminas finísimas de plomo.", "words": [{"w": "El", "s": 274.5, "e": 274.6}, {"w": "acelerador", "s": 274.6, "e": 275.14}, {"w": "disparaba", "s": 275.14, "e": 275.76}, {"w": "unos", "s": 275.76, "e": 276.14}, {"w": "dos", "s": 276.43, "e": 276.72}, {"w": "billones", "s": 276.72, "e": 277.18}, {"w": "de", "s": 277.18, "e": 277.44}, {"w": "átomos", "s": 277.44, "e": 277.74}, {"w": "de", "s": 277.74, "e": 277.92}, {"w": "criptón", "s": 278.14, "e": 278.36}, {"w": "por", "s": 278.36, "e": 278.74}, {"w": "segundo", "s": 278.74, "e": 279.12}, {"w": "contra", "s": 279.12, "e": 279.5}, {"w": "láminas", "s": 279.5, "e": 280.04}, {"w": "finísimas", "s": 280.04, "e": 280.56}, {"w": "de", "s": 280.56, "e": 280.74}, {"w": "plomo.", "s": 280.74, "e": 281.08}]}, {"id": "c55", "start": 281.579, "end": 283.295, "text": "Así, durante once días.", "words": [{"w": "Así,", "s": 281.52, "e": 281.88}, {"w": "durante", "s": 282.14, "e": 282.18}, {"w": "once", "s": 282.42, "e": 282.66}, {"w": "días.", "s": 282.66, "e": 283.08}]}, {"id": "c56", "start": 285.195, "end": 286.947, "text": "Y Ninov encontró algo.", "words": [{"w": "Y", "s": 285.098, "e": 285.0}, {"w": "Ninov", "s": 285.0, "e": 285.76}, {"w": "encontró", "s": 285.76, "e": 286.38}, {"w": "algo.", "s": 286.38, "e": 286.78}]}, {"id": "c57", "start": 287.367, "end": 288.429, "text": "Tres cadenas.", "words": [{"w": "Tres", "s": 287.493, "e": 287.62}, {"w": "cadenas.", "s": 287.62, "e": 288.18}]}, {"id": "c58", "start": 288.849, "end": 296.312, "text": "En cada una, un átomo pesado que se clavaba en el detector y, después, seis desintegraciones seguidas, en menos de un segundo.", "words": [{"w": "En", "s": 288.82, "e": 288.98}, {"w": "cada", "s": 288.98, "e": 289.22}, {"w": "una,", "s": 289.22, "e": 289.56}, {"w": "un", "s": 289.56, "e": 289.84}, {"w": "átomo", "s": 289.84, "e": 290.1}, {"w": "pesado", "s": 290.1, "e": 290.58}, {"w": "que", "s": 290.58, "e": 290.74}, {"w": "se", "s": 290.74, "e": 290.88}, {"w": "clavaba", "s": 290.88, "e": 291.26}, {"w": "en", "s": 291.26, "e": 291.4}, {"w": "el", "s": 291.4, "e": 291.5}, {"w": "detector", "s": 291.5, "e": 291.9}, {"w": "y,", "s": 291.9, "e": 292.14}, {"w": "después,", "s": 292.14, "e": 292.94}, {"w": "seis", "s": 293.23, "e": 293.52}, {"w": "desintegraciones", "s": 293.52, "e": 294.3}, {"w": "seguidas,", "s": 294.3, "e": 294.9}, {"w": "en", "s": 294.9, "e": 295.24}, {"w": "menos", "s": 295.24, "e": 295.46}, {"w": "de", "s": 295.46, "e": 295.64}, {"w": "un", "s": 295.64, "e": 295.72}, {"w": "segundo.", "s": 295.72, "e": 296.22}]}, {"id": "c59", "start": 296.732, "end": 300.009, "text": "Justo lo que se esperaba del elemento ciento dieciocho.", "words": [{"w": "Justo", "s": 296.68, "e": 297.12}, {"w": "lo", "s": 297.12, "e": 297.24}, {"w": "que", "s": 297.24, "e": 297.4}, {"w": "se", "s": 297.4, "e": 297.54}, {"w": "esperaba", "s": 297.54, "e": 298.04}, {"w": "del", "s": 298.04, "e": 298.24}, {"w": "elemento", "s": 298.24, "e": 298.6}, {"w": "ciento", "s": 298.952, "e": 299.252}, {"w": "dieciocho.", "s": 299.657, "e": 299.957}]}, {"id": "c60", "start": 300.429, "end": 304.948, "text": "Y en el camino, como un escalón de la cadena, el elemento ciento dieciséis.", "words": [{"w": "Y", "s": 300.3, "e": 300.52}, {"w": "en", "s": 300.52, "e": 300.62}, {"w": "el", "s": 300.62, "e": 300.72}, {"w": "camino,", "s": 300.72, "e": 301.08}, {"w": "como", "s": 301.08, "e": 301.38}, {"w": "un", "s": 301.38, "e": 301.54}, {"w": "escalón", "s": 301.54, "e": 301.98}, {"w": "de", "s": 301.98, "e": 302.08}, {"w": "la", "s": 302.08, "e": 302.18}, {"w": "cadena,", "s": 302.18, "e": 302.62}, {"w": "el", "s": 303.04, "e": 303.08}, {"w": "elemento", "s": 303.08, "e": 303.5}, {"w": "ciento", "s": 303.862, "e": 304.162}, {"w": "dieciséis.", "s": 304.586, "e": 304.886}]}, {"id": "c61", "start": 305.898, "end": 309.278, "text": "Tres átomos de un elemento que nadie había visto jamás.", "words": [{"w": "Tres", "s": 305.989, "e": 306.08}, {"w": "átomos", "s": 306.08, "e": 306.48}, {"w": "de", "s": 306.48, "e": 306.68}, {"w": "un", "s": 306.68, "e": 306.78}, {"w": "elemento", "s": 306.78, "e": 307.2}, {"w": "que", "s": 307.2, "e": 307.66}, {"w": "nadie", "s": 307.66, "e": 307.94}, {"w": "había", "s": 307.94, "e": 308.3}, {"w": "visto", "s": 308.3, "e": 308.66}, {"w": "jamás.", "s": 308.66, "e": 309.2}]}, {"id": "c62", "start": 309.698, "end": 312.717, "text": "Casi exactamente como había predicho Smolańczuk.", "words": [{"w": "Casi", "s": 309.64, "e": 309.98}, {"w": "exactamente", "s": 309.98, "e": 310.6}, {"w": "como", "s": 310.6, "e": 311.18}, {"w": "había", "s": 311.18, "e": 311.52}, {"w": "predicho", "s": 311.819, "e": 312.119}, {"w": "Smolańczuk.", "s": 312.418, "e": 312.717}]}, {"id": "cap3", "start": 313.667, "end": 317.667}, {"id": "c63", "start": 317.667, "end": 322.536, "text": "Hay una idea que obsesiona a los físicos desde hace décadas: la isla de estabilidad.", "words": [{"w": "Hay", "s": 317.743, "e": 317.82}, {"w": "una", "s": 317.82, "e": 318.0}, {"w": "idea", "s": 318.0, "e": 318.28}, {"w": "que", "s": 318.28, "e": 318.5}, {"w": "obsesiona", "s": 318.5, "e": 319.06}, {"w": "a", "s": 319.06, "e": 319.2}, {"w": "los", "s": 319.2, "e": 319.3}, {"w": "físicos", "s": 319.3, "e": 319.78}, {"w": "desde", "s": 319.78, "e": 319.98}, {"w": "hace", "s": 319.98, "e": 320.32}, {"w": "décadas:", "s": 320.32, "e": 320.8}, {"w": "la", "s": 321.22, "e": 321.42}, {"w": "isla", "s": 321.42, "e": 321.76}, {"w": "de", "s": 321.76, "e": 321.88}, {"w": "estabilidad.", "s": 321.88, "e": 322.46}]}, {"id": "c64", "start": 322.956, "end": 332.122, "text": "La teoría dice que, más allá de la zona de los elementos que se desarman en un instante, podría haber una región de núcleos más estables, que vivan mucho más.", "words": [{"w": "La", "s": 322.92, "e": 323.08}, {"w": "teoría", "s": 323.08, "e": 323.48}, {"w": "dice", "s": 323.48, "e": 323.8}, {"w": "que,", "s": 323.8, "e": 324.04}, {"w": "más", "s": 324.04, "e": 324.3}, {"w": "allá", "s": 324.3, "e": 324.56}, {"w": "de", "s": 324.56, "e": 324.74}, {"w": "la", "s": 324.74, "e": 324.84}, {"w": "zona", "s": 324.84, "e": 325.08}, {"w": "de", "s": 325.08, "e": 325.24}, {"w": "los", "s": 325.24, "e": 325.34}, {"w": "elementos", "s": 325.34, "e": 325.8}, {"w": "que", "s": 325.8, "e": 326.08}, {"w": "se", "s": 326.08, "e": 326.24}, {"w": "desarman", "s": 326.24, "e": 326.72}, {"w": "en", "s": 326.72, "e": 326.84}, {"w": "un", "s": 326.84, "e": 326.94}, {"w": "instante,", "s": 326.94, "e": 327.5}, {"w": "podría", "s": 327.5, "e": 328.16}, {"w": "haber", "s": 328.16, "e": 328.46}, {"w": "una", "s": 328.46, "e": 328.72}, {"w": "región", "s": 328.72, "e": 329.08}, {"w": "de", "s": 329.08, "e": 329.28}, {"w": "núcleos", "s": 329.28, "e": 329.78}, {"w": "más", "s": 329.78, "e": 329.96}, {"w": "estables,", "s": 329.96, "e": 330.54}, {"w": "que", "s": 330.54, "e": 331.0}, {"w": "vivan", "s": 331.0, "e": 331.34}, {"w": "mucho", "s": 331.34, "e": 331.64}, {"w": "más.", "s": 331.64, "e": 331.9}]}, {"id": "c65", "start": 332.542, "end": 336.366, "text": "Algunos sueñan con que duren minutos, días, o incluso años.", "words": [{"w": "Algunos", "s": 332.52, "e": 332.98}, {"w": "sueñan", "s": 332.98, "e": 333.32}, {"w": "con", "s": 333.32, "e": 333.52}, {"w": "que", "s": 333.52, "e": 333.66}, {"w": "duren", "s": 333.66, "e": 333.9}, {"w": "minutos,", "s": 333.9, "e": 334.34}, {"w": "días,", "s": 334.82, "e": 335.06}, {"w": "o", "s": 335.06, "e": 335.38}, {"w": "incluso", "s": 335.38, "e": 335.74}, {"w": "años.", "s": 335.74, "e": 336.12}]}, {"id": "c66", "start": 337.316, "end": 342.53, "text": "El resultado de Berkeley parecía mostrar que esa isla existía, y que se podía llegar.", "words": [{"w": "El", "s": 337.368, "e": 337.42}, {"w": "resultado", "s": 337.42, "e": 337.86}, {"w": "de", "s": 337.86, "e": 338.1}, {"w": "Berkeley", "s": 338.1, "e": 338.42}, {"w": "parecía", "s": 338.42, "e": 339.02}, {"w": "mostrar", "s": 339.02, "e": 339.46}, {"w": "que", "s": 339.46, "e": 339.72}, {"w": "esa", "s": 339.72, "e": 339.94}, {"w": "isla", "s": 339.94, "e": 340.26}, {"w": "existía,", "s": 340.26, "e": 340.92}, {"w": "y", "s": 340.92, "e": 341.34}, {"w": "que", "s": 341.34, "e": 341.46}, {"w": "se", "s": 341.46, "e": 341.62}, {"w": "podía", "s": 341.62, "e": 341.98}, {"w": "llegar.", "s": 341.98, "e": 342.36}]}, {"id": "c67", "start": 343.48, "end": 345.695, "text": "El anuncio fue un acontecimiento.", "words": [{"w": "El", "s": 343.18, "e": 343.6}, {"w": "anuncio", "s": 343.6, "e": 344.04}, {"w": "fue", "s": 344.04, "e": 344.34}, {"w": "un", "s": 344.34, "e": 344.62}, {"w": "acontecimiento.", "s": 344.62, "e": 345.54}]}, {"id": "c68", "start": 346.115, "end": 351.209, "text": "Ninov, primer autor del trabajo, lo resumió con una frase que salió en todos lados:", "words": [{"w": "Ninov,", "s": 346.06, "e": 346.58}, {"w": "primer", "s": 346.68, "e": 346.92}, {"w": "autor", "s": 346.92, "e": 347.22}, {"w": "del", "s": 347.22, "e": 347.48}, {"w": "trabajo,", "s": 347.48, "e": 347.94}, {"w": "lo", "s": 348.38, "e": 348.48}, {"w": "resumió", "s": 348.48, "e": 348.96}, {"w": "con", "s": 348.96, "e": 349.18}, {"w": "una", "s": 349.18, "e": 349.34}, {"w": "frase", "s": 349.34, "e": 349.68}, {"w": "que", "s": 349.68, "e": 349.88}, {"w": "salió", "s": 349.88, "e": 350.24}, {"w": "en", "s": 350.24, "e": 350.38}, {"w": "todos", "s": 350.38, "e": 350.58}, {"w": "lados:", "s": 350.58, "e": 351.02}]}, {"id": "c69", "start": 351.629, "end": 356.046, "text": "Saltamos por encima de un mar de inestabilidad, hasta una isla de estabilidad.", "words": [{"w": "Saltamos", "s": 351.62, "e": 352.06}, {"w": "por", "s": 352.06, "e": 352.32}, {"w": "encima", "s": 352.32, "e": 352.7}, {"w": "de", "s": 352.7, "e": 352.88}, {"w": "un", "s": 352.88, "e": 352.98}, {"w": "mar", "s": 352.98, "e": 353.24}, {"w": "de", "s": 353.24, "e": 353.36}, {"w": "inestabilidad,", "s": 353.36, "e": 354.08}, {"w": "hasta", "s": 354.08, "e": 354.66}, {"w": "una", "s": 354.66, "e": 354.9}, {"w": "isla", "s": 354.9, "e": 355.28}, {"w": "de", "s": 355.28, "e": 355.4}, {"w": "estabilidad.", "s": 355.4, "e": 355.98}]}, {"id": "c70", "start": 356.996, "end": 366.639, "text": "Darleane Hoffman, una de las grandes químicas de los elementos pesados, dijo que después de treinta años de búsqueda, el descubrimiento era enormemente gratificante.", "words": [{"w": "Darleane", "s": 357.148, "e": 357.3}, {"w": "Hoffman,", "s": 357.3, "e": 357.8}, {"w": "una", "s": 358.02, "e": 358.16}, {"w": "de", "s": 358.16, "e": 358.28}, {"w": "las", "s": 358.28, "e": 358.42}, {"w": "grandes", "s": 358.42, "e": 358.7}, {"w": "químicas", "s": 358.7, "e": 359.28}, {"w": "de", "s": 359.28, "e": 359.44}, {"w": "los", "s": 359.44, "e": 359.58}, {"w": "elementos", "s": 359.58, "e": 359.96}, {"w": "pesados,", "s": 359.96, "e": 360.56}, {"w": "dijo", "s": 361.12, "e": 361.38}, {"w": "que", "s": 361.38, "e": 361.56}, {"w": "después", "s": 361.56, "e": 361.86}, {"w": "de", "s": 361.86, "e": 362.1}, {"w": "treinta", "s": 362.26, "e": 362.42}, {"w": "años", "s": 362.42, "e": 362.78}, {"w": "de", "s": 362.78, "e": 362.94}, {"w": "búsqueda,", "s": 362.94, "e": 363.4}, {"w": "el", "s": 363.84, "e": 363.92}, {"w": "descubrimiento", "s": 363.92, "e": 364.6}, {"w": "era", "s": 364.6, "e": 364.9}, {"w": "enormemente", "s": 364.9, "e": 365.72}, {"w": "gratificante.", "s": 365.72, "e": 366.56}]}, {"id": "c71", "start": 367.059, "end": 375.32, "text": "Y Albert Ghiorso, una leyenda que había participado en el descubrimiento de doce elementos, veía en Ninov a una versión más joven de sí mismo.", "words": [{"w": "Y", "s": 367.0, "e": 367.18}, {"w": "Albert", "s": 367.18, "e": 367.51}, {"w": "Ghiorso,", "s": 367.9, "e": 368.2}, {"w": "una", "s": 368.29, "e": 368.45}, {"w": "leyenda", "s": 368.45, "e": 368.85}, {"w": "que", "s": 368.85, "e": 369.05}, {"w": "había", "s": 369.05, "e": 369.31}, {"w": "participado", "s": 369.31, "e": 370.05}, {"w": "en", "s": 370.05, "e": 370.19}, {"w": "el", "s": 370.19, "e": 370.29}, {"w": "descubrimiento", "s": 370.29, "e": 370.93}, {"w": "de", "s": 370.93, "e": 371.07}, {"w": "doce", "s": 371.16, "e": 371.25}, {"w": "elementos,", "s": 371.25, "e": 371.77}, {"w": "veía", "s": 372.33, "e": 372.71}, {"w": "en", "s": 372.71, "e": 372.87}, {"w": "Ninov", "s": 372.87, "e": 373.23}, {"w": "a", "s": 373.23, "e": 373.41}, {"w": "una", "s": 373.41, "e": 373.53}, {"w": "versión", "s": 373.53, "e": 373.87}, {"w": "más", "s": 373.87, "e": 374.27}, {"w": "joven", "s": 374.27, "e": 374.57}, {"w": "de", "s": 374.57, "e": 374.71}, {"w": "sí", "s": 374.71, "e": 374.89}, {"w": "mismo.", "s": 374.89, "e": 375.27}]}, {"id": "c72", "start": 376.27, "end": 383.242, "text": "El trabajo se publicó en agosto en Physical Review Letters, una de las revistas de física más importantes del mundo.", "words": [{"w": "El", "s": 376.21, "e": 376.39}, {"w": "trabajo", "s": 376.39, "e": 376.71}, {"w": "se", "s": 376.71, "e": 376.99}, {"w": "publicó", "s": 376.99, "e": 377.47}, {"w": "en", "s": 377.47, "e": 377.59}, {"w": "agosto", "s": 377.59, "e": 377.97}, {"w": "en", "s": 377.97, "e": 378.15}, {"w": "Physical", "s": 378.41, "e": 378.67}, {"w": "Review", "s": 378.67, "e": 379.03}, {"w": "Letters,", "s": 379.03, "e": 379.67}, {"w": "una", "s": 380.09, "e": 380.23}, {"w": "de", "s": 380.23, "e": 380.37}, {"w": "las", "s": 380.37, "e": 380.49}, {"w": "revistas", "s": 380.49, "e": 380.91}, {"w": "de", "s": 380.91, "e": 381.13}, {"w": "física", "s": 381.13, "e": 381.47}, {"w": "más", "s": 381.47, "e": 381.89}, {"w": "importantes", "s": 381.89, "e": 382.49}, {"w": "del", "s": 382.49, "e": 382.83}, {"w": "mundo.", "s": 382.83, "e": 383.11}]}, {"id": "c73", "start": 383.662, "end": 386.876, "text": "Ninov empezó a dar charlas en otros laboratorios.", "words": [{"w": "Ninov", "s": 383.61, "e": 384.05}, {"w": "empezó", "s": 384.05, "e": 384.59}, {"w": "a", "s": 384.59, "e": 384.71}, {"w": "dar", "s": 384.71, "e": 384.83}, {"w": "charlas", "s": 384.83, "e": 385.35}, {"w": "en", "s": 385.35, "e": 385.71}, {"w": "otros", "s": 385.71, "e": 385.91}, {"w": "laboratorios.", "s": 385.91, "e": 386.73}]}, {"id": "c74", "start": 387.826, "end": 389.482, "text": "Solo faltaba una cosa.", "words": [{"w": "Solo", "s": 387.77, "e": 388.11}, {"w": "faltaba", "s": 388.11, "e": 388.65}, {"w": "una", "s": 388.65, "e": 388.85}, {"w": "cosa.", "s": 388.85, "e": 389.27}]}, {"id": "c75", "start": 389.902, "end": 391.941, "text": "La que siempre falta en ciencia.", "words": [{"w": "La", "s": 389.93, "e": 390.01}, {"w": "que", "s": 390.01, "e": 390.17}, {"w": "siempre", "s": 390.17, "e": 390.49}, {"w": "falta", "s": 390.49, "e": 390.99}, {"w": "en", "s": 390.99, "e": 391.27}, {"w": "ciencia.", "s": 391.27, "e": 391.77}]}, {"id": "c76", "start": 392.361, "end": 394.318, "text": "Que alguien más lo repitiera.", "words": [{"w": "Que", "s": 392.33, "e": 392.49}, {"w": "alguien", "s": 392.49, "e": 392.87}, {"w": "más", "s": 392.87, "e": 393.33}, {"w": "lo", "s": 393.33, "e": 393.51}, {"w": "repitiera.", "s": 393.51, "e": 394.21}]}, {"id": "cap4", "start": 395.268, "end": 399.268}, {"id": "c77", "start": 399.268, "end": 406.83, "text": "Ese mismo año, el equipo de GSI en Darmstadt, el lugar donde se había formado Ninov, intentó reproducir el experimento.", "words": [{"w": "Ese", "s": 399.349, "e": 399.43}, {"w": "mismo", "s": 399.43, "e": 399.73}, {"w": "año,", "s": 399.73, "e": 400.11}, {"w": "el", "s": 400.43, "e": 400.45}, {"w": "equipo", "s": 400.45, "e": 400.73}, {"w": "de", "s": 400.73, "e": 400.91}, {"w": "GSI", "s": 400.91, "e": 401.45}, {"w": "en", "s": 401.45, "e": 401.63}, {"w": "Darmstadt,", "s": 401.63, "e": 402.07}, {"w": "el", "s": 402.53, "e": 402.61}, {"w": "lugar", "s": 402.61, "e": 402.89}, {"w": "donde", "s": 402.89, "e": 403.11}, {"w": "se", "s": 403.11, "e": 403.37}, {"w": "había", "s": 403.37, "e": 403.59}, {"w": "formado", "s": 403.59, "e": 404.07}, {"w": "Ninov,", "s": 404.07, "e": 404.55}, {"w": "intentó", "s": 404.89, "e": 405.35}, {"w": "reproducir", "s": 405.35, "e": 405.91}, {"w": "el", "s": 405.91, "e": 406.07}, {"w": "experimento.", "s": 406.07, "e": 406.87}]}, {"id": "c78", "start": 407.25, "end": 408.574, "text": "No encontró nada.", "words": [{"w": "No", "s": 407.21, "e": 407.43}, {"w": "encontró", "s": 407.43, "e": 408.03}, {"w": "nada.", "s": 408.03, "e": 408.33}]}, {"id": "c79", "start": 408.994, "end": 411.55, "text": "En Japón, el instituto RIKEN tampoco.", "words": [{"w": "En", "s": 408.93, "e": 409.11}, {"w": "Japón,", "s": 409.11, "e": 409.57}, {"w": "el", "s": 409.79, "e": 409.85}, {"w": "instituto", "s": 409.85, "e": 410.35}, {"w": "RIKEN", "s": 410.59, "e": 410.83}, {"w": "tampoco.", "s": 410.83, "e": 411.21}]}, {"id": "c80", "start": 411.97, "end": 414.622, "text": "En Francia, el laboratorio GANIL tampoco.", "words": [{"w": "En", "s": 411.85, "e": 412.09}, {"w": "Francia,", "s": 412.09, "e": 412.61}, {"w": "el", "s": 412.87, "e": 412.93}, {"w": "laboratorio", "s": 412.93, "e": 413.49}, {"w": "GANIL", "s": 413.49, "e": 413.89}, {"w": "tampoco.", "s": 413.89, "e": 414.33}]}, {"id": "c81", "start": 415.572, "end": 417.599, "text": "Al principio no era tan raro.", "words": [{"w": "Al", "s": 415.51, "e": 415.69}, {"w": "principio", "s": 415.69, "e": 416.19}, {"w": "no", "s": 416.19, "e": 416.71}, {"w": "era", "s": 416.71, "e": 416.89}, {"w": "tan", "s": 416.89, "e": 417.13}, {"w": "raro.", "s": 417.13, "e": 417.53}]}, {"id": "c82", "start": 418.019, "end": 425.069, "text": "Fabricar un átomo así es dificilísimo, y cualquier diferencia en el haz o en el detector puede cambiar el resultado.", "words": [{"w": "Fabricar", "s": 418.01, "e": 418.49}, {"w": "un", "s": 418.49, "e": 418.63}, {"w": "átomo", "s": 418.63, "e": 418.91}, {"w": "así", "s": 418.91, "e": 419.29}, {"w": "es", "s": 419.29, "e": 419.55}, {"w": "dificilísimo,", "s": 419.55, "e": 420.41}, {"w": "y", "s": 420.71, "e": 420.91}, {"w": "cualquier", "s": 420.91, "e": 421.19}, {"w": "diferencia", "s": 421.19, "e": 421.71}, {"w": "en", "s": 421.71, "e": 422.11}, {"w": "el", "s": 422.11, "e": 422.25}, {"w": "haz", "s": 422.34, "e": 422.43}, {"w": "o", "s": 422.43, "e": 422.75}, {"w": "en", "s": 422.75, "e": 422.85}, {"w": "el", "s": 422.85, "e": 422.93}, {"w": "detector", "s": 422.93, "e": 423.43}, {"w": "puede", "s": 423.43, "e": 423.79}, {"w": "cambiar", "s": 423.79, "e": 424.15}, {"w": "el", "s": 424.15, "e": 424.39}, {"w": "resultado.", "s": 424.39, "e": 424.89}]}, {"id": "c83", "start": 426.019, "end": 432.896, "text": "Pero en el año dos mil, el propio equipo de Berkeley repitió el experimento, con el mismo acelerador y el mismo método.", "words": [{"w": "Pero", "s": 425.79, "e": 426.15}, {"w": "en", "s": 426.15, "e": 426.29}, {"w": "el", "s": 426.29, "e": 426.39}, {"w": "año", "s": 426.39, "e": 426.55}, {"w": "dos", "s": 426.77, "e": 427.07}, {"w": "mil,", "s": 427.21, "e": 427.43}, {"w": "el", "s": 427.43, "e": 427.57}, {"w": "propio", "s": 427.57, "e": 427.83}, {"w": "equipo", "s": 427.83, "e": 428.29}, {"w": "de", "s": 428.29, "e": 428.49}, {"w": "Berkeley", "s": 428.67, "e": 428.85}, {"w": "repitió", "s": 428.85, "e": 429.29}, {"w": "el", "s": 429.29, "e": 429.41}, {"w": "experimento,", "s": 429.41, "e": 430.33}, {"w": "con", "s": 430.39, "e": 430.57}, {"w": "el", "s": 430.57, "e": 430.71}, {"w": "mismo", "s": 430.71, "e": 430.99}, {"w": "acelerador", "s": 430.99, "e": 431.65}, {"w": "y", "s": 431.65, "e": 431.95}, {"w": "el", "s": 431.95, "e": 432.05}, {"w": "mismo", "s": 432.05, "e": 432.33}, {"w": "método.", "s": 432.33, "e": 432.77}]}, {"id": "c84", "start": 433.316, "end": 435.171, "text": "Y tampoco encontró nada.", "words": [{"w": "Y", "s": 433.27, "e": 433.43}, {"w": "tampoco", "s": 433.43, "e": 433.83}, {"w": "encontró", "s": 433.83, "e": 434.67}, {"w": "nada.", "s": 434.67, "e": 435.01}]}, {"id": "c85", "start": 437.071, "end": 438.564, "text": "Revisaron el equipo.", "words": [{"w": "Revisaron", "s": 437.01, "e": 437.67}, {"w": "el", "s": 437.67, "e": 437.91}, {"w": "equipo.", "s": 437.91, "e": 438.29}]}, {"id": "c86", "start": 438.984, "end": 440.438, "text": "Cambiaron detalles.", "words": [{"w": "Cambiaron", "s": 439.01, "e": 439.53}, {"w": "detalles.", "s": 439.53, "e": 440.17}]}, {"id": "c87", "start": 440.858, "end": 442.199, "text": "Siguieron midiendo.", "words": [{"w": "Siguieron", "s": 440.97, "e": 441.35}, {"w": "midiendo.", "s": 441.35, "e": 442.01}]}, {"id": "c88", "start": 443.149, "end": 446.092, "text": "En abril de dos mil uno hicieron otra corrida.", "words": [{"w": "En", "s": 443.13, "e": 443.27}, {"w": "abril", "s": 443.27, "e": 443.55}, {"w": "de", "s": 443.55, "e": 443.71}, {"w": "dos", "s": 443.905, "e": 444.205}, {"w": "mil", "s": 444.295, "e": 444.49}, {"w": "uno", "s": 444.49, "e": 444.69}, {"w": "hicieron", "s": 444.69, "e": 445.15}, {"w": "otra", "s": 445.15, "e": 445.47}, {"w": "corrida.", "s": 445.47, "e": 445.97}]}, {"id": "c89", "start": 446.512, "end": 452.445, "text": "Y esta vez, el programa de análisis de Ninov encontró una nueva cadena del elemento ciento dieciocho.", "words": [{"w": "Y", "s": 446.55, "e": 446.63}, {"w": "esta", "s": 446.63, "e": 446.85}, {"w": "vez,", "s": 446.85, "e": 447.05}, {"w": "el", "s": 447.35, "e": 447.41}, {"w": "programa", "s": 447.41, "e": 447.73}, {"w": "de", "s": 447.73, "e": 447.95}, {"w": "análisis", "s": 447.95, "e": 448.41}, {"w": "de", "s": 448.41, "e": 448.57}, {"w": "Ninov", "s": 448.57, "e": 449.01}, {"w": "encontró", "s": 449.01, "e": 449.75}, {"w": "una", "s": 449.75, "e": 449.97}, {"w": "nueva", "s": 449.97, "e": 450.27}, {"w": "cadena", "s": 450.27, "e": 450.75}, {"w": "del", "s": 450.75, "e": 450.93}, {"w": "elemento", "s": 450.93, "e": 451.29}, {"w": "ciento", "s": 451.579, "e": 451.879}, {"w": "dieciocho.", "s": 452.156, "e": 452.445}]}, {"id": "c90", "start": 453.395, "end": 455.653, "text": "Pero esta vez pasó algo distinto.", "words": [{"w": "Pero", "s": 453.25, "e": 453.55}, {"w": "esta", "s": 453.55, "e": 453.83}, {"w": "vez", "s": 453.83, "e": 454.05}, {"w": "pasó", "s": 454.05, "e": 454.53}, {"w": "algo", "s": 454.53, "e": 454.87}, {"w": "distinto.", "s": 454.87, "e": 455.49}]}, {"id": "c91", "start": 456.073, "end": 461.05, "text": "Otros miembros del equipo ya habían escrito sus propios programas para leer los datos.", "words": [{"w": "Otros", "s": 456.07, "e": 456.33}, {"w": "miembros", "s": 456.33, "e": 456.79}, {"w": "del", "s": 456.79, "e": 456.95}, {"w": "equipo", "s": 456.95, "e": 457.29}, {"w": "ya", "s": 457.29, "e": 457.85}, {"w": "habían", "s": 457.85, "e": 458.21}, {"w": "escrito", "s": 458.21, "e": 458.55}, {"w": "sus", "s": 458.55, "e": 458.89}, {"w": "propios", "s": 458.89, "e": 459.29}, {"w": "programas", "s": 459.29, "e": 459.91}, {"w": "para", "s": 459.91, "e": 460.09}, {"w": "leer", "s": 460.09, "e": 460.31}, {"w": "los", "s": 460.31, "e": 460.53}, {"w": "datos.", "s": 460.53, "e": 460.85}]}, {"id": "c92", "start": 461.47, "end": 464.426, "text": "Y cuando buscaron esa cadena en el mismo archivo,", "words": [{"w": "Y", "s": 461.43, "e": 461.57}, {"w": "cuando", "s": 461.57, "e": 461.75}, {"w": "buscaron", "s": 461.75, "e": 462.37}, {"w": "esa", "s": 462.37, "e": 462.61}, {"w": "cadena", "s": 462.61, "e": 463.13}, {"w": "en", "s": 463.13, "e": 463.39}, {"w": "el", "s": 463.39, "e": 463.51}, {"w": "mismo", "s": 463.51, "e": 463.81}, {"w": "archivo,", "s": 463.81, "e": 464.33}]}, {"id": "c93", "start": 464.846, "end": 465.791, "text": "no estaba.", "words": [{"w": "no", "s": 464.81, "e": 465.03}, {"w": "estaba.", "s": 465.03, "e": 468.73}]}, {"id": "cap5", "start": 466.741, "end": 470.741}, {"id": "c94", "start": 470.741, "end": 476.121, "text": "Si la cadena de dos mil uno no aparecía en los datos, había que hacer una pregunta incómoda.", "words": [{"w": "Si", "s": 470.795, "e": 470.85}, {"w": "la", "s": 470.85, "e": 470.99}, {"w": "cadena", "s": 470.99, "e": 471.33}, {"w": "de", "s": 471.33, "e": 471.45}, {"w": "dos", "s": 471.515, "e": 471.71}, {"w": "mil", "s": 471.645, "e": 471.71}, {"w": "uno", "s": 471.71, "e": 472.23}, {"w": "no", "s": 472.23, "e": 472.41}, {"w": "aparecía", "s": 472.41, "e": 472.97}, {"w": "en", "s": 472.97, "e": 473.09}, {"w": "los", "s": 473.09, "e": 473.21}, {"w": "datos,", "s": 473.21, "e": 473.59}, {"w": "había", "s": 474.01, "e": 474.25}, {"w": "que", "s": 474.25, "e": 474.51}, {"w": "hacer", "s": 474.51, "e": 474.75}, {"w": "una", "s": 474.75, "e": 474.95}, {"w": "pregunta", "s": 474.95, "e": 475.37}, {"w": "incómoda.", "s": 475.37, "e": 476.09}]}, {"id": "c95", "start": 476.541, "end": 479.697, "text": "¿Qué pasaba con las de mil novecientos noventa y nueve?", "words": [{"w": "¿Qué", "s": 476.55, "e": 476.65}, {"w": "pasaba", "s": 476.65, "e": 477.15}, {"w": "con", "s": 477.15, "e": 477.37}, {"w": "las", "s": 477.37, "e": 477.53}, {"w": "de", "s": 477.53, "e": 477.67}, {"w": "mil", "s": 477.873, "e": 478.173}, {"w": "novecientos", "s": 478.278, "e": 478.578}, {"w": "noventa", "s": 478.683, "e": 478.983}, {"w": "y", "s": 479.089, "e": 479.389}, {"w": "nueve?", "s": 479.494, "e": 479.697}]}, {"id": "c96", "start": 480.647, "end": 487.809, "text": "En mil novecientos noventa y nueve, Ninov había sido el único del equipo que trabajó directamente con los datos en bruto.", "words": [{"w": "En", "s": 480.59, "e": 480.77}, {"w": "mil", "s": 480.978, "e": 481.278}, {"w": "novecientos", "s": 481.394, "e": 481.694}, {"w": "noventa", "s": 481.81, "e": 482.11}, {"w": "y", "s": 482.226, "e": 482.526}, {"w": "nueve,", "s": 482.642, "e": 482.85}, {"w": "Ninov", "s": 482.85, "e": 483.29}, {"w": "había", "s": 483.29, "e": 483.51}, {"w": "sido", "s": 483.51, "e": 483.87}, {"w": "el", "s": 483.87, "e": 484.03}, {"w": "único", "s": 484.03, "e": 484.29}, {"w": "del", "s": 484.29, "e": 484.51}, {"w": "equipo", "s": 484.51, "e": 484.89}, {"w": "que", "s": 484.89, "e": 485.21}, {"w": "trabajó", "s": 485.21, "e": 485.69}, {"w": "directamente", "s": 485.69, "e": 486.27}, {"w": "con", "s": 486.27, "e": 486.65}, {"w": "los", "s": 486.65, "e": 486.81}, {"w": "datos", "s": 486.81, "e": 487.11}, {"w": "en", "s": 487.11, "e": 487.39}, {"w": "bruto.", "s": 487.39, "e": 487.67}]}, {"id": "c97", "start": 488.229, "end": 490.949, "text": "Los demás habían confiado en su análisis.", "words": [{"w": "Los", "s": 488.21, "e": 488.37}, {"w": "demás", "s": 488.37, "e": 488.69}, {"w": "habían", "s": 488.69, "e": 489.23}, {"w": "confiado", "s": 489.23, "e": 489.89}, {"w": "en", "s": 489.89, "e": 490.09}, {"w": "su", "s": 490.09, "e": 490.25}, {"w": "análisis.", "s": 490.25, "e": 490.79}]}, {"id": "c98", "start": 491.899, "end": 501.82, "text": "Un grupo coordinado por Darleane Hoffman volvió a los archivos originales de mil novecientos noventa y nueve, los que salieron del detector durante esos once días.", "words": [{"w": "Un", "s": 491.75, "e": 492.03}, {"w": "grupo", "s": 492.03, "e": 492.25}, {"w": "coordinado", "s": 492.25, "e": 492.93}, {"w": "por", "s": 492.93, "e": 493.17}, {"w": "Darleane", "s": 493.48, "e": 493.78}, {"w": "Hoffman", "s": 494.1, "e": 494.4}, {"w": "volvió", "s": 494.41, "e": 494.81}, {"w": "a", "s": 494.81, "e": 494.89}, {"w": "los", "s": 494.89, "e": 495.03}, {"w": "archivos", "s": 495.03, "e": 495.41}, {"w": "originales", "s": 495.41, "e": 496.15}, {"w": "de", "s": 496.15, "e": 496.29}, {"w": "mil", "s": 496.518, "e": 496.818}, {"w": "novecientos", "s": 496.974, "e": 497.274}, {"w": "noventa", "s": 497.43, "e": 497.73}, {"w": "y", "s": 497.886, "e": 498.186}, {"w": "nueve,", "s": 498.342, "e": 498.57}, {"w": "los", "s": 498.57, "e": 498.77}, {"w": "que", "s": 498.77, "e": 498.95}, {"w": "salieron", "s": 498.95, "e": 499.37}, {"w": "del", "s": 499.37, "e": 499.59}, {"w": "detector", "s": 499.59, "e": 499.93}, {"w": "durante", "s": 499.93, "e": 500.47}, {"w": "esos", "s": 500.47, "e": 500.85}, {"w": "once", "s": 501.05, "e": 501.25}, {"w": "días.", "s": 501.25, "e": 501.59}]}, {"id": "c99", "start": 502.24, "end": 505.36, "text": "Los leyeron con otros programas, evento por evento.", "words": [{"w": "Los", "s": 502.17, "e": 502.39}, {"w": "leyeron", "s": 502.39, "e": 502.85}, {"w": "con", "s": 502.85, "e": 503.03}, {"w": "otros", "s": 503.03, "e": 503.23}, {"w": "programas,", "s": 503.23, "e": 504.05}, {"w": "evento", "s": 504.05, "e": 504.51}, {"w": "por", "s": 504.51, "e": 504.83}, {"w": "evento.", "s": 504.83, "e": 505.21}]}, {"id": "c100", "start": 506.31, "end": 508.251, "text": "Las tres cadenas no estaban.", "words": [{"w": "Las", "s": 506.11, "e": 506.47}, {"w": "tres", "s": 506.47, "e": 506.71}, {"w": "cadenas", "s": 506.71, "e": 507.21}, {"w": "no", "s": 507.21, "e": 507.65}, {"w": "estaban.", "s": 507.65, "e": 508.03}]}, {"id": "c101", "start": 508.671, "end": 511.545, "text": "No eran dudosas, ni estaban mal interpretadas.", "words": [{"w": "No", "s": 508.59, "e": 508.83}, {"w": "eran", "s": 508.83, "e": 509.01}, {"w": "dudosas,", "s": 509.01, "e": 509.57}, {"w": "ni", "s": 509.57, "e": 509.95}, {"w": "estaban", "s": 509.95, "e": 510.33}, {"w": "mal", "s": 510.33, "e": 510.65}, {"w": "interpretadas.", "s": 510.65, "e": 511.39}]}, {"id": "c102", "start": 511.965, "end": 512.846, "text": "No estaban.", "words": [{"w": "No", "s": 511.93, "e": 512.15}, {"w": "estaban.", "s": 512.15, "e": 512.61}]}, {"id": "c103", "start": 513.266, "end": 519.146, "text": "En los datos que había registrado el detector no había ningún rastro del elemento ciento dieciocho.", "words": [{"w": "En", "s": 513.25, "e": 513.37}, {"w": "los", "s": 513.37, "e": 513.51}, {"w": "datos", "s": 513.51, "e": 513.83}, {"w": "que", "s": 513.83, "e": 514.09}, {"w": "había", "s": 514.09, "e": 514.31}, {"w": "registrado", "s": 514.31, "e": 514.97}, {"w": "el", "s": 514.97, "e": 515.13}, {"w": "detector", "s": 515.13, "e": 515.59}, {"w": "no", "s": 516.09, "e": 516.19}, {"w": "había", "s": 516.19, "e": 516.49}, {"w": "ningún", "s": 516.49, "e": 516.93}, {"w": "rastro", "s": 516.93, "e": 517.47}, {"w": "del", "s": 517.47, "e": 517.61}, {"w": "elemento", "s": 517.61, "e": 517.93}, {"w": "ciento", "s": 518.234, "e": 518.534}, {"w": "dieciocho.", "s": 518.842, "e": 519.142}]}, {"id": "c104", "start": 519.566, "end": 521.64, "text": "Tampoco del ciento dieciséis.", "words": [{"w": "Tampoco", "s": 519.51, "e": 520.05}, {"w": "del", "s": 520.05, "e": 520.31}, {"w": "ciento", "s": 520.642, "e": 520.942}, {"w": "dieciséis.", "s": 521.307, "e": 521.607}]}, {"id": "c105", "start": 522.59, "end": 526.985, "text": "El veintisiete de julio de dos mil uno, Berkeley retiró el descubrimiento.", "words": [{"w": "El", "s": 522.33, "e": 522.69}, {"w": "veintisiete", "s": 522.92, "e": 523.15}, {"w": "de", "s": 523.15, "e": 523.43}, {"w": "julio", "s": 523.43, "e": 523.79}, {"w": "de", "s": 523.79, "e": 523.89}, {"w": "dos", "s": 524.093, "e": 524.393}, {"w": "mil", "s": 524.5, "e": 524.8}, {"w": "uno,", "s": 524.907, "e": 525.11}, {"w": "Berkeley", "s": 525.11, "e": 525.41}, {"w": "retiró", "s": 525.41, "e": 525.97}, {"w": "el", "s": 525.97, "e": 526.07}, {"w": "descubrimiento.", "s": 526.07, "e": 526.85}]}, {"id": "c106", "start": 527.405, "end": 538.214, "text": "El equipo escribió que, después de volver a analizar los datos primarios, había llegado a una conclusión: las tres cadenas no estaban en los datos de mil novecientos noventa y nueve.", "words": [{"w": "El", "s": 527.37, "e": 527.53}, {"w": "equipo", "s": 527.53, "e": 527.75}, {"w": "escribió", "s": 527.75, "e": 528.31}, {"w": "que,", "s": 528.31, "e": 528.49}, {"w": "después", "s": 528.81, "e": 528.97}, {"w": "de", "s": 528.97, "e": 529.15}, {"w": "volver", "s": 529.15, "e": 529.35}, {"w": "a", "s": 529.35, "e": 529.61}, {"w": "analizar", "s": 529.61, "e": 530.01}, {"w": "los", "s": 530.01, "e": 530.27}, {"w": "datos", "s": 530.27, "e": 530.49}, {"w": "primarios,", "s": 530.49, "e": 531.11}, {"w": "había", "s": 531.57, "e": 531.81}, {"w": "llegado", "s": 531.81, "e": 532.35}, {"w": "a", "s": 532.35, "e": 532.51}, {"w": "una", "s": 532.51, "e": 532.63}, {"w": "conclusión:", "s": 532.63, "e": 533.31}, {"w": "las", "s": 533.87, "e": 534.05}, {"w": "tres", "s": 534.05, "e": 534.31}, {"w": "cadenas", "s": 534.31, "e": 534.75}, {"w": "no", "s": 534.75, "e": 535.07}, {"w": "estaban", "s": 535.07, "e": 535.45}, {"w": "en", "s": 535.45, "e": 535.61}, {"w": "los", "s": 535.61, "e": 535.73}, {"w": "datos", "s": 535.73, "e": 536.01}, {"w": "de", "s": 536.01, "e": 536.23}, {"w": "mil", "s": 536.428, "e": 536.728}, {"w": "novecientos", "s": 536.825, "e": 537.125}, {"w": "noventa", "s": 537.222, "e": 537.522}, {"w": "y", "s": 537.619, "e": 537.919}, {"w": "nueve.", "s": 538.016, "e": 538.214}]}, {"id": "c107", "start": 539.164, "end": 542.696, "text": "Ninov pidió que su nombre no figurara en esa retractación.", "words": [{"w": "Ninov", "s": 538.93, "e": 539.53}, {"w": "pidió", "s": 539.53, "e": 539.93}, {"w": "que", "s": 539.93, "e": 540.09}, {"w": "su", "s": 540.09, "e": 540.29}, {"w": "nombre", "s": 540.29, "e": 540.59}, {"w": "no", "s": 540.59, "e": 540.87}, {"w": "figurara", "s": 540.87, "e": 541.37}, {"w": "en", "s": 541.37, "e": 541.61}, {"w": "esa", "s": 541.61, "e": 541.79}, {"w": "retractación.", "s": 541.79, "e": 542.57}]}, {"id": "c108", "start": 543.116, "end": 547.509, "text": "Por eso la revista recién publicó una nota editorial un año después.", "words": [{"w": "Por", "s": 543.07, "e": 543.25}, {"w": "eso", "s": 543.25, "e": 543.45}, {"w": "la", "s": 543.45, "e": 543.63}, {"w": "revista", "s": 543.63, "e": 544.07}, {"w": "recién", "s": 544.07, "e": 544.59}, {"w": "publicó", "s": 544.59, "e": 545.23}, {"w": "una", "s": 545.23, "e": 545.39}, {"w": "nota", "s": 545.39, "e": 545.65}, {"w": "editorial", "s": 545.65, "e": 546.21}, {"w": "un", "s": 546.21, "e": 546.61}, {"w": "año", "s": 546.61, "e": 546.81}, {"w": "después.", "s": 546.81, "e": 547.21}]}, {"id": "c109", "start": 549.409, "end": 552.584, "text": "Ahora la pregunta ya no era si el elemento existía.", "words": [{"w": "Ahora", "s": 549.25, "e": 549.63}, {"w": "la", "s": 549.63, "e": 549.83}, {"w": "pregunta", "s": 549.83, "e": 550.19}, {"w": "ya", "s": 550.19, "e": 550.63}, {"w": "no", "s": 550.63, "e": 550.93}, {"w": "era", "s": 550.93, "e": 551.15}, {"w": "si", "s": 551.15, "e": 551.39}, {"w": "el", "s": 551.39, "e": 551.51}, {"w": "elemento", "s": 551.51, "e": 551.77}, {"w": "existía.", "s": 551.77, "e": 552.53}]}, {"id": "c110", "start": 553.004, "end": 553.874, "text": "Era otra.", "words": [{"w": "Era", "s": 553.067, "e": 553.13}, {"w": "otra.", "s": 553.13, "e": 553.59}]}, {"id": "c111", "start": 554.294, "end": 557.994, "text": "Si las cadenas no estaban en los datos, ¿de dónde habían salido?", "words": [{"w": "Si", "s": 554.27, "e": 554.39}, {"w": "las", "s": 554.39, "e": 554.57}, {"w": "cadenas", "s": 554.57, "e": 554.97}, {"w": "no", "s": 554.97, "e": 555.23}, {"w": "estaban", "s": 555.23, "e": 555.57}, {"w": "en", "s": 555.57, "e": 555.75}, {"w": "los", "s": 555.75, "e": 555.87}, {"w": "datos,", "s": 555.87, "e": 556.21}, {"w": "¿de", "s": 556.21, "e": 556.65}, {"w": "dónde", "s": 556.65, "e": 556.91}, {"w": "habían", "s": 556.91, "e": 557.39}, {"w": "salido?", "s": 557.39, "e": 557.93}]}, {"id": "cap6", "start": 558.944, "end": 562.944}, {"id": "c112", "start": 562.944, "end": 567.614, "text": "El laboratorio armó primero un comité técnico, que trabajó unos cuatro meses.", "words": [{"w": "El", "s": 563.007, "e": 563.07}, {"w": "laboratorio", "s": 563.07, "e": 563.65}, {"w": "armó", "s": 563.65, "e": 564.03}, {"w": "primero", "s": 564.03, "e": 564.41}, {"w": "un", "s": 564.41, "e": 564.63}, {"w": "comité", "s": 564.63, "e": 564.97}, {"w": "técnico,", "s": 564.97, "e": 565.63}, {"w": "que", "s": 565.63, "e": 565.95}, {"w": "trabajó", "s": 565.95, "e": 566.47}, {"w": "unos", "s": 566.47, "e": 566.67}, {"w": "cuatro", "s": 566.67, "e": 566.95}, {"w": "meses.", "s": 566.95, "e": 567.39}]}, {"id": "c113", "start": 568.034, "end": 577.164, "text": "Después, en noviembre de dos mil uno, un comité formal de investigación, presidido por el físico Rochus Vogt, del Instituto de Tecnología de California.", "words": [{"w": "Después,", "s": 568.03, "e": 568.31}, {"w": "en", "s": 568.63, "e": 568.67}, {"w": "noviembre", "s": 568.67, "e": 569.07}, {"w": "de", "s": 569.07, "e": 569.21}, {"w": "dos", "s": 569.377, "e": 569.677}, {"w": "mil", "s": 569.71, "e": 570.01}, {"w": "uno,", "s": 570.043, "e": 570.21}, {"w": "un", "s": 570.21, "e": 570.37}, {"w": "comité", "s": 570.37, "e": 570.73}, {"w": "formal", "s": 570.73, "e": 571.05}, {"w": "de", "s": 571.05, "e": 571.29}, {"w": "investigación,", "s": 571.29, "e": 571.91}, {"w": "presidido", "s": 572.39, "e": 572.89}, {"w": "por", "s": 572.89, "e": 573.09}, {"w": "el", "s": 573.09, "e": 573.21}, {"w": "físico", "s": 573.21, "e": 573.67}, {"w": "Rochus", "s": 573.9, "e": 574.13}, {"w": "Vogt,", "s": 574.13, "e": 574.55}, {"w": "del", "s": 574.87, "e": 574.97}, {"w": "Instituto", "s": 574.97, "e": 575.47}, {"w": "de", "s": 575.47, "e": 575.71}, {"w": "Tecnología", "s": 575.71, "e": 576.23}, {"w": "de", "s": 576.23, "e": 576.47}, {"w": "California.", "s": 576.47, "e": 576.91}]}, {"id": "c114", "start": 578.114, "end": 581.472, "text": "En marzo de dos mil dos, el comité entregó su informe.", "words": [{"w": "En", "s": 578.172, "e": 578.23}, {"w": "marzo", "s": 578.23, "e": 578.59}, {"w": "de", "s": 578.59, "e": 578.69}, {"w": "dos", "s": 578.873, "e": 579.173}, {"w": "mil", "s": 579.24, "e": 579.54}, {"w": "dos,", "s": 579.607, "e": 579.79}, {"w": "el", "s": 579.79, "e": 579.85}, {"w": "comité", "s": 579.85, "e": 580.25}, {"w": "entregó", "s": 580.25, "e": 580.71}, {"w": "su", "s": 580.71, "e": 580.87}, {"w": "informe.", "s": 580.87, "e": 581.45}]}, {"id": "c115", "start": 581.892, "end": 590.023, "text": "Encontró, dice el informe, evidencia clara y convincente de que los datos de mil novecientos noventa y nueve habían sido fabricados.", "words": [{"w": "Encontró,", "s": 581.83, "e": 582.43}, {"w": "dice", "s": 582.63, "e": 582.81}, {"w": "el", "s": 582.81, "e": 582.97}, {"w": "informe,", "s": 582.97, "e": 583.61}, {"w": "evidencia", "s": 583.93, "e": 584.41}, {"w": "clara", "s": 584.41, "e": 584.79}, {"w": "y", "s": 584.79, "e": 584.99}, {"w": "convincente", "s": 584.99, "e": 585.59}, {"w": "de", "s": 585.59, "e": 585.75}, {"w": "que", "s": 585.75, "e": 585.83}, {"w": "los", "s": 585.83, "e": 585.99}, {"w": "datos", "s": 585.99, "e": 586.23}, {"w": "de", "s": 586.23, "e": 586.41}, {"w": "mil", "s": 586.497, "e": 586.797}, {"w": "novecientos", "s": 586.67, "e": 586.93}, {"w": "noventa", "s": 586.843, "e": 586.93}, {"w": "y", "s": 586.93, "e": 588.03}, {"w": "nueve", "s": 588.17, "e": 588.31}, {"w": "habían", "s": 588.31, "e": 588.75}, {"w": "sido", "s": 588.75, "e": 589.23}, {"w": "fabricados.", "s": 589.23, "e": 589.85}]}, {"id": "c116", "start": 590.443, "end": 593.4, "text": "Y concluyó que el responsable era Victor Ninov.", "words": [{"w": "Y", "s": 590.41, "e": 590.55}, {"w": "concluyó", "s": 590.55, "e": 591.11}, {"w": "que", "s": 591.11, "e": 591.23}, {"w": "el", "s": 591.23, "e": 591.31}, {"w": "responsable", "s": 591.31, "e": 592.07}, {"w": "era", "s": 592.07, "e": 592.47}, {"w": "Victor", "s": 592.47, "e": 592.85}, {"w": "Ninov.", "s": 592.85, "e": 593.37}]}, {"id": "c117", "start": 594.35, "end": 601.146, "text": "El informe también criticó al resto del equipo, por no haber tenido a nadie más que revisara los datos originales.", "words": [{"w": "El", "s": 594.31, "e": 594.47}, {"w": "informe", "s": 594.47, "e": 595.01}, {"w": "también", "s": 595.01, "e": 595.21}, {"w": "criticó", "s": 595.21, "e": 595.85}, {"w": "al", "s": 595.85, "e": 596.01}, {"w": "resto", "s": 596.01, "e": 596.27}, {"w": "del", "s": 596.27, "e": 596.43}, {"w": "equipo,", "s": 596.43, "e": 596.85}, {"w": "por", "s": 596.85, "e": 597.45}, {"w": "no", "s": 597.45, "e": 597.59}, {"w": "haber", "s": 597.59, "e": 597.83}, {"w": "tenido", "s": 597.83, "e": 598.23}, {"w": "a", "s": 598.23, "e": 598.49}, {"w": "nadie", "s": 598.49, "e": 598.69}, {"w": "más", "s": 598.69, "e": 599.11}, {"w": "que", "s": 599.11, "e": 599.29}, {"w": "revisara", "s": 599.58, "e": 599.87}, {"w": "los", "s": 599.87, "e": 599.99}, {"w": "datos", "s": 599.99, "e": 600.25}, {"w": "originales.", "s": 600.25, "e": 601.09}]}, {"id": "c118", "start": 602.096, "end": 605.063, "text": "En mayo de dos mil dos, Berkeley despidió a Ninov.", "words": [{"w": "En", "s": 602.163, "e": 602.23}, {"w": "mayo", "s": 602.23, "e": 602.45}, {"w": "de", "s": 602.45, "e": 602.61}, {"w": "dos", "s": 602.787, "e": 603.087}, {"w": "mil", "s": 603.14, "e": 603.44}, {"w": "dos,", "s": 603.493, "e": 603.67}, {"w": "Berkeley", "s": 603.67, "e": 603.99}, {"w": "despidió", "s": 603.99, "e": 604.57}, {"w": "a", "s": 604.57, "e": 604.69}, {"w": "Ninov.", "s": 604.69, "e": 605.07}]}, {"id": "c119", "start": 606.014, "end": 608.063, "text": "Él nunca aceptó la acusación.", "words": [{"w": "Él", "s": 605.89, "e": 606.15}, {"w": "nunca", "s": 606.15, "e": 606.51}, {"w": "aceptó", "s": 606.51, "e": 607.13}, {"w": "la", "s": 607.13, "e": 607.25}, {"w": "acusación.", "s": 607.25, "e": 607.87}]}, {"id": "c120", "start": 608.483, "end": 617.068, "text": "Escribió que en ningún momento había participado, a sabiendas, en ninguna forma de tergiversación de datos, ni de mala conducta científica.", "words": [{"w": "Escribió", "s": 608.43, "e": 608.97}, {"w": "que", "s": 608.97, "e": 609.09}, {"w": "en", "s": 609.09, "e": 609.21}, {"w": "ningún", "s": 609.21, "e": 609.45}, {"w": "momento", "s": 609.45, "e": 609.89}, {"w": "había", "s": 609.89, "e": 610.25}, {"w": "participado,", "s": 610.25, "e": 611.07}, {"w": "a", "s": 611.07, "e": 611.51}, {"w": "sabiendas,", "s": 611.51, "e": 612.27}, {"w": "en", "s": 612.27, "e": 612.55}, {"w": "ninguna", "s": 612.55, "e": 612.83}, {"w": "forma", "s": 612.83, "e": 613.19}, {"w": "de", "s": 613.19, "e": 613.37}, {"w": "tergiversación", "s": 613.37, "e": 614.17}, {"w": "de", "s": 614.17, "e": 614.35}, {"w": "datos,", "s": 614.35, "e": 614.69}, {"w": "ni", "s": 615.07, "e": 615.33}, {"w": "de", "s": 615.33, "e": 615.45}, {"w": "mala", "s": 615.45, "e": 615.65}, {"w": "conducta", "s": 615.65, "e": 616.27}, {"w": "científica.", "s": 616.27, "e": 617.03}]}, {"id": "c121", "start": 617.488, "end": 620.166, "text": "Inició un reclamo formal contra el despido.", "words": [{"w": "Inició", "s": 617.41, "e": 617.89}, {"w": "un", "s": 617.89, "e": 618.07}, {"w": "reclamo", "s": 618.07, "e": 618.57}, {"w": "formal", "s": 618.57, "e": 618.93}, {"w": "contra", "s": 618.93, "e": 619.41}, {"w": "el", "s": 619.41, "e": 619.57}, {"w": "despido.", "s": 619.57, "e": 620.07}]}, {"id": "c122", "start": 620.586, "end": 623.626, "text": "Y dijo una frase que resume cómo vivió todo esto:", "words": [{"w": "Y", "s": 620.55, "e": 620.69}, {"w": "dijo", "s": 620.69, "e": 620.97}, {"w": "una", "s": 620.97, "e": 621.13}, {"w": "frase", "s": 621.13, "e": 621.53}, {"w": "que", "s": 621.53, "e": 621.85}, {"w": "resume", "s": 621.85, "e": 622.25}, {"w": "cómo", "s": 622.25, "e": 622.51}, {"w": "vivió", "s": 622.51, "e": 622.91}, {"w": "todo", "s": 622.91, "e": 623.13}, {"w": "esto:", "s": 623.13, "e": 623.45}]}, {"id": "c123", "start": 624.046, "end": 627.933, "text": "Una vez que te marcan como falsificador, empieza la avalancha.", "words": [{"w": "Una", "s": 624.03, "e": 624.19}, {"w": "vez", "s": 624.19, "e": 624.47}, {"w": "que", "s": 624.47, "e": 624.65}, {"w": "te", "s": 624.65, "e": 624.79}, {"w": "marcan", "s": 624.79, "e": 625.19}, {"w": "como", "s": 625.19, "e": 625.49}, {"w": "falsificador,", "s": 625.49, "e": 626.39}, {"w": "empieza", "s": 626.63, "e": 627.03}, {"w": "la", "s": 627.03, "e": 627.29}, {"w": "avalancha.", "s": 627.29, "e": 627.85}]}, {"id": "c124", "start": 629.833, "end": 635.554, "text": "Porque mientras tanto, en Darmstadt, el equipo de GSI había hecho algo que nadie le había pedido.", "words": [{"w": "Porque", "s": 629.921, "e": 630.01}, {"w": "mientras", "s": 630.01, "e": 630.31}, {"w": "tanto,", "s": 630.31, "e": 630.81}, {"w": "en", "s": 631.07, "e": 631.13}, {"w": "Darmstadt,", "s": 631.13, "e": 631.61}, {"w": "el", "s": 632.09, "e": 632.17}, {"w": "equipo", "s": 632.17, "e": 632.43}, {"w": "de", "s": 632.43, "e": 632.61}, {"w": "GSI", "s": 632.8, "e": 632.99}, {"w": "había", "s": 632.99, "e": 633.35}, {"w": "hecho", "s": 633.35, "e": 633.79}, {"w": "algo", "s": 633.79, "e": 634.09}, {"w": "que", "s": 634.09, "e": 634.31}, {"w": "nadie", "s": 634.31, "e": 634.59}, {"w": "le", "s": 634.59, "e": 634.79}, {"w": "había", "s": 634.79, "e": 635.01}, {"w": "pedido.", "s": 635.01, "e": 635.51}]}, {"id": "c125", "start": 635.974, "end": 642.884, "text": "Revisó los datos de sus propios descubrimientos, de mil novecientos noventa y cuatro a mil novecientos noventa y seis.", "words": [{"w": "Revisó", "s": 635.99, "e": 636.37}, {"w": "los", "s": 636.37, "e": 636.55}, {"w": "datos", "s": 636.55, "e": 636.77}, {"w": "de", "s": 636.77, "e": 636.99}, {"w": "sus", "s": 636.99, "e": 637.13}, {"w": "propios", "s": 637.13, "e": 637.51}, {"w": "descubrimientos,", "s": 637.51, "e": 638.35}, {"w": "de", "s": 638.35, "e": 638.93}, {"w": "mil", "s": 639.043, "e": 639.343}, {"w": "novecientos", "s": 639.27, "e": 639.57}, {"w": "noventa", "s": 639.497, "e": 639.61}, {"w": "y", "s": 639.61, "e": 640.53}, {"w": "cuatro", "s": 640.65, "e": 640.77}, {"w": "a", "s": 640.77, "e": 640.97}, {"w": "mil", "s": 641.161, "e": 641.461}, {"w": "novecientos", "s": 641.544, "e": 641.844}, {"w": "noventa", "s": 641.927, "e": 642.227}, {"w": "y", "s": 642.31, "e": 642.61}, {"w": "seis.", "s": 642.693, "e": 642.884}]}, {"id": "c126", "start": 643.834, "end": 645.861, "text": "Eran treinta y cuatro cadenas.", "words": [{"w": "Eran", "s": 643.993, "e": 644.293}, {"w": "treinta", "s": 644.312, "e": 644.612}, {"w": "y", "s": 644.631, "e": 644.931}, {"w": "cuatro", "s": 644.95, "e": 645.11}, {"w": "cadenas.", "s": 645.11, "e": 645.67}]}, {"id": "c127", "start": 646.281, "end": 655.666, "text": "Dos no aparecían en los datos: una del elemento ciento diez, de mil novecientos noventa y cuatro, y una del ciento doce, de mil novecientos noventa y seis.", "words": [{"w": "Dos", "s": 646.25, "e": 646.47}, {"w": "no", "s": 646.47, "e": 646.63}, {"w": "aparecían", "s": 646.63, "e": 647.21}, {"w": "en", "s": 647.21, "e": 647.35}, {"w": "los", "s": 647.35, "e": 647.47}, {"w": "datos:", "s": 647.47, "e": 647.79}, {"w": "una", "s": 648.41, "e": 648.61}, {"w": "del", "s": 648.61, "e": 648.77}, {"w": "elemento", "s": 648.77, "e": 649.11}, {"w": "ciento", "s": 649.3, "e": 649.6}, {"w": "diez,", "s": 649.68, "e": 649.87}, {"w": "de", "s": 649.87, "e": 650.23}, {"w": "mil", "s": 650.31, "e": 650.61}, {"w": "novecientos", "s": 650.47, "e": 650.77}, {"w": "noventa", "s": 650.63, "e": 650.93}, {"w": "y", "s": 650.79, "e": 651.03}, {"w": "cuatro,", "s": 650.95, "e": 651.03}, {"w": "y", "s": 651.03, "e": 652.35}, {"w": "una", "s": 652.35, "e": 652.51}, {"w": "del", "s": 652.51, "e": 652.63}, {"w": "ciento", "s": 652.77, "e": 653.07}, {"w": "doce,", "s": 653.05, "e": 653.19}, {"w": "de", "s": 653.19, "e": 653.75}, {"w": "mil", "s": 653.942, "e": 654.242}, {"w": "novecientos", "s": 654.325, "e": 654.625}, {"w": "noventa", "s": 654.708, "e": 655.008}, {"w": "y", "s": 655.091, "e": 655.391}, {"w": "seis.", "s": 655.474, "e": 655.666}]}, {"id": "c128", "start": 656.086, "end": 659.591, "text": "Los investigadores descartaron que fuera un error simple.", "words": [{"w": "Los", "s": 656.03, "e": 656.23}, {"w": "investigadores", "s": 656.23, "e": 656.99}, {"w": "descartaron", "s": 656.99, "e": 657.91}, {"w": "que", "s": 657.91, "e": 658.11}, {"w": "fuera", "s": 658.11, "e": 658.43}, {"w": "un", "s": 658.43, "e": 658.73}, {"w": "error", "s": 658.73, "e": 658.95}, {"w": "simple.", "s": 658.95, "e": 659.43}]}, {"id": "c129", "start": 660.011, "end": 662.818, "text": "Eran análisis en los que había trabajado Ninov.", "words": [{"w": "Eran", "s": 659.97, "e": 660.27}, {"w": "análisis", "s": 660.27, "e": 660.83}, {"w": "en", "s": 660.83, "e": 661.17}, {"w": "los", "s": 661.17, "e": 661.29}, {"w": "que", "s": 661.29, "e": 661.47}, {"w": "había", "s": 661.47, "e": 661.77}, {"w": "trabajado", "s": 661.77, "e": 662.37}, {"w": "Ninov.", "s": 662.37, "e": 662.83}]}, {"id": "c130", "start": 663.768, "end": 670.588, "text": "Los descubrimientos de Darmstadt se mantuvieron, porque las demás cadenas eran reales y alcanzaban para probarlos.", "words": [{"w": "Los", "s": 663.829, "e": 663.89}, {"w": "descubrimientos", "s": 663.89, "e": 664.61}, {"w": "de", "s": 664.61, "e": 664.79}, {"w": "Darmstadt", "s": 664.79, "e": 665.27}, {"w": "se", "s": 665.27, "e": 665.57}, {"w": "mantuvieron,", "s": 665.57, "e": 666.23}, {"w": "porque", "s": 666.23, "e": 666.87}, {"w": "las", "s": 666.87, "e": 667.09}, {"w": "demás", "s": 667.09, "e": 667.33}, {"w": "cadenas", "s": 667.33, "e": 667.83}, {"w": "eran", "s": 667.83, "e": 668.23}, {"w": "reales", "s": 668.23, "e": 668.83}, {"w": "y", "s": 668.83, "e": 668.95}, {"w": "alcanzaban", "s": 668.95, "e": 669.61}, {"w": "para", "s": 669.61, "e": 669.85}, {"w": "probarlos.", "s": 669.85, "e": 670.47}]}, {"id": "c131", "start": 671.008, "end": 673.824, "text": "Pero dos de las pruebas no estaban en los datos.", "words": [{"w": "Pero", "s": 670.89, "e": 671.19}, {"w": "dos", "s": 671.19, "e": 671.41}, {"w": "de", "s": 671.41, "e": 671.53}, {"w": "las", "s": 671.53, "e": 671.65}, {"w": "pruebas", "s": 671.65, "e": 672.13}, {"w": "no", "s": 672.13, "e": 672.55}, {"w": "estaban", "s": 672.55, "e": 672.95}, {"w": "en", "s": 672.95, "e": 673.11}, {"w": "los", "s": 673.11, "e": 673.25}, {"w": "datos.", "s": 673.25, "e": 673.59}]}, {"id": "epi", "start": 674.774, "end": 678.774}, {"id": "c132", "start": 678.774, "end": 682.505, "text": "Los elementos ciento dieciséis y ciento dieciocho existen.", "words": [{"w": "Los", "s": 678.852, "e": 678.93}, {"w": "elementos", "s": 678.93, "e": 679.33}, {"w": "ciento", "s": 679.625, "e": 679.925}, {"w": "dieciséis", "s": 680.215, "e": 680.51}, {"w": "y", "s": 680.51, "e": 680.93}, {"w": "ciento", "s": 681.14, "e": 681.44}, {"w": "dieciocho", "s": 681.56, "e": 681.77}, {"w": "existen.", "s": 681.77, "e": 682.45}]}, {"id": "c133", "start": 682.925, "end": 690.715, "text": "Los crearon, de verdad, en Dubna, un equipo ruso junto a científicos del Laboratorio Nacional Lawrence Livermore, de Estados Unidos.", "words": [{"w": "Los", "s": 682.89, "e": 683.09}, {"w": "crearon,", "s": 683.09, "e": 683.57}, {"w": "de", "s": 683.75, "e": 683.81}, {"w": "verdad,", "s": 683.81, "e": 684.17}, {"w": "en", "s": 684.45, "e": 684.51}, {"w": "Dubna,", "s": 684.51, "e": 684.89}, {"w": "un", "s": 685.27, "e": 685.39}, {"w": "equipo", "s": 685.39, "e": 685.61}, {"w": "ruso", "s": 685.61, "e": 686.03}, {"w": "junto", "s": 686.03, "e": 686.29}, {"w": "a", "s": 686.29, "e": 686.49}, {"w": "científicos", "s": 686.49, "e": 687.19}, {"w": "del", "s": 687.19, "e": 687.33}, {"w": "Laboratorio", "s": 687.33, "e": 687.87}, {"w": "Nacional", "s": 687.87, "e": 688.37}, {"w": "Lawrence", "s": 688.37, "e": 688.75}, {"w": "Livermore,", "s": 688.75, "e": 689.39}, {"w": "de", "s": 689.39, "e": 689.75}, {"w": "Estados", "s": 689.75, "e": 690.05}, {"w": "Unidos.", "s": 690.05, "e": 690.53}]}, {"id": "c134", "start": 691.135, "end": 693.715, "text": "El ciento dieciséis, en el año dos mil.", "words": [{"w": "El", "s": 691.11, "e": 691.29}, {"w": "ciento", "s": 691.515, "e": 691.815}, {"w": "dieciséis,", "s": 691.965, "e": 692.19}, {"w": "en", "s": 692.19, "e": 692.61}, {"w": "el", "s": 692.61, "e": 692.75}, {"w": "año", "s": 692.75, "e": 692.97}, {"w": "dos", "s": 693.156, "e": 693.456}, {"w": "mil.", "s": 693.529, "e": 693.715}]}, {"id": "c135", "start": 694.135, "end": 700.075, "text": "El ciento dieciocho, en experimentos de dos mil dos y dos mil cinco, anunciados en dos mil seis.", "words": [{"w": "El", "s": 694.09, "e": 694.29}, {"w": "ciento", "s": 694.495, "e": 694.795}, {"w": "dieciocho,", "s": 694.905, "e": 695.11}, {"w": "en", "s": 695.11, "e": 695.51}, {"w": "experimentos", "s": 695.51, "e": 696.19}, {"w": "de", "s": 696.19, "e": 696.27}, {"w": "dos", "s": 696.36, "e": 696.66}, {"w": "mil", "s": 696.54, "e": 696.81}, {"w": "dos", "s": 696.72, "e": 696.81}, {"w": "y", "s": 696.81, "e": 697.25}, {"w": "dos", "s": 697.36, "e": 697.66}, {"w": "mil", "s": 697.58, "e": 697.88}, {"w": "cinco,", "s": 697.8, "e": 697.91}, {"w": "anunciados", "s": 697.91, "e": 698.93}, {"w": "en", "s": 698.93, "e": 699.15}, {"w": "dos", "s": 699.304, "e": 699.604}, {"w": "mil", "s": 699.612, "e": 699.912}, {"w": "seis.", "s": 699.921, "e": 700.075}]}, {"id": "c136", "start": 701.025, "end": 703.24, "text": "Hoy se llaman livermorio y oganesón.", "words": [{"w": "Hoy", "s": 700.99, "e": 701.21}, {"w": "se", "s": 701.21, "e": 701.39}, {"w": "llaman", "s": 701.39, "e": 701.71}, {"w": "livermorio", "s": 702.11, "e": 702.41}, {"w": "y", "s": 702.51, "e": 702.65}, {"w": "oganesón.", "s": 702.65, "e": 703.21}]}, {"id": "c137", "start": 703.66, "end": 707.4, "text": "Y no se hicieron con la receta de criptón y plomo, sino con otra.", "words": [{"w": "Y", "s": 703.705, "e": 703.75}, {"w": "no", "s": 703.75, "e": 703.91}, {"w": "se", "s": 703.91, "e": 704.07}, {"w": "hicieron", "s": 704.07, "e": 704.45}, {"w": "con", "s": 704.45, "e": 704.69}, {"w": "la", "s": 704.69, "e": 704.83}, {"w": "receta", "s": 704.83, "e": 705.21}, {"w": "de", "s": 705.21, "e": 705.35}, {"w": "criptón", "s": 705.56, "e": 705.77}, {"w": "y", "s": 705.77, "e": 706.01}, {"w": "plomo,", "s": 706.01, "e": 706.35}, {"w": "sino", "s": 706.55, "e": 706.73}, {"w": "con", "s": 706.73, "e": 706.99}, {"w": "otra.", "s": 706.99, "e": 707.23}]}, {"id": "c138", "start": 709.3, "end": 711.099, "text": "El caso cambió las reglas.", "words": [{"w": "El", "s": 709.365, "e": 709.43}, {"w": "caso", "s": 709.43, "e": 709.81}, {"w": "cambió", "s": 709.81, "e": 710.29}, {"w": "las", "s": 710.29, "e": 710.51}, {"w": "reglas.", "s": 710.51, "e": 710.91}]}, {"id": "c139", "start": 711.519, "end": 720.004, "text": "La Sociedad Estadounidense de Física pidió más formación en ética, y que cada coautor de un trabajo pueda responder por la parte que firma.", "words": [{"w": "La", "s": 711.51, "e": 711.65}, {"w": "Sociedad", "s": 711.65, "e": 712.07}, {"w": "Estadounidense", "s": 712.07, "e": 712.99}, {"w": "de", "s": 712.99, "e": 713.17}, {"w": "Física", "s": 713.17, "e": 713.61}, {"w": "pidió", "s": 713.61, "e": 714.11}, {"w": "más", "s": 714.11, "e": 714.37}, {"w": "formación", "s": 714.37, "e": 714.93}, {"w": "en", "s": 714.93, "e": 715.17}, {"w": "ética,", "s": 715.17, "e": 715.57}, {"w": "y", "s": 715.57, "e": 716.11}, {"w": "que", "s": 716.11, "e": 716.23}, {"w": "cada", "s": 716.23, "e": 716.49}, {"w": "coautor", "s": 716.49, "e": 717.01}, {"w": "de", "s": 717.01, "e": 717.11}, {"w": "un", "s": 717.11, "e": 717.21}, {"w": "trabajo", "s": 717.21, "e": 717.63}, {"w": "pueda", "s": 717.63, "e": 718.03}, {"w": "responder", "s": 718.03, "e": 718.55}, {"w": "por", "s": 718.55, "e": 718.85}, {"w": "la", "s": 718.85, "e": 718.99}, {"w": "parte", "s": 718.99, "e": 719.31}, {"w": "que", "s": 719.31, "e": 719.51}, {"w": "firma.", "s": 719.51, "e": 719.93}]}, {"id": "c140", "start": 720.424, "end": 727.186, "text": "Nunca más un descubrimiento debería depender de una sola persona, y de un programa que solo esa persona entiende.", "words": [{"w": "Nunca", "s": 720.43, "e": 720.73}, {"w": "más", "s": 720.73, "e": 720.99}, {"w": "un", "s": 720.99, "e": 721.13}, {"w": "descubrimiento", "s": 721.13, "e": 721.87}, {"w": "debería", "s": 721.87, "e": 722.39}, {"w": "depender", "s": 722.39, "e": 722.81}, {"w": "de", "s": 722.81, "e": 723.05}, {"w": "una", "s": 723.05, "e": 723.17}, {"w": "sola", "s": 723.17, "e": 723.43}, {"w": "persona,", "s": 723.43, "e": 723.99}, {"w": "y", "s": 723.99, "e": 724.55}, {"w": "de", "s": 724.55, "e": 724.67}, {"w": "un", "s": 724.67, "e": 724.81}, {"w": "programa", "s": 724.81, "e": 725.25}, {"w": "que", "s": 725.25, "e": 725.53}, {"w": "solo", "s": 725.53, "e": 725.83}, {"w": "esa", "s": 725.83, "e": 726.09}, {"w": "persona", "s": 726.09, "e": 726.55}, {"w": "entiende.", "s": 726.55, "e": 727.09}]}, {"id": "c141", "start": 728.136, "end": 730.723, "text": "Ninov siempre sostuvo que es inocente.", "words": [{"w": "Ninov", "s": 728.07, "e": 728.51}, {"w": "siempre", "s": 728.51, "e": 728.79}, {"w": "sostuvo", "s": 728.79, "e": 729.49}, {"w": "que", "s": 729.49, "e": 729.79}, {"w": "es", "s": 729.79, "e": 729.95}, {"w": "inocente.", "s": 729.95, "e": 730.55}]}, {"id": "c142", "start": 731.673, "end": 734.782, "text": "La ciencia tiene una regla que no se puede esquivar.", "words": [{"w": "La", "s": 731.63, "e": 731.81}, {"w": "ciencia", "s": 731.81, "e": 732.21}, {"w": "tiene", "s": 732.21, "e": 732.55}, {"w": "una", "s": 732.55, "e": 732.75}, {"w": "regla", "s": 732.75, "e": 733.17}, {"w": "que", "s": 733.17, "e": 733.53}, {"w": "no", "s": 733.53, "e": 733.71}, {"w": "se", "s": 733.71, "e": 733.91}, {"w": "puede", "s": 733.91, "e": 734.13}, {"w": "esquivar.", "s": 734.13, "e": 734.73}]}, {"id": "c143", "start": 735.202, "end": 741.189, "text": "Un resultado no vale porque lo diga alguien prestigioso, ni porque salga en una revista importante.", "words": [{"w": "Un", "s": 735.21, "e": 735.33}, {"w": "resultado", "s": 735.33, "e": 735.73}, {"w": "no", "s": 735.73, "e": 736.09}, {"w": "vale", "s": 736.09, "e": 736.39}, {"w": "porque", "s": 736.39, "e": 736.65}, {"w": "lo", "s": 736.65, "e": 736.87}, {"w": "diga", "s": 736.87, "e": 737.15}, {"w": "alguien", "s": 737.15, "e": 737.47}, {"w": "prestigioso,", "s": 737.47, "e": 738.29}, {"w": "ni", "s": 738.29, "e": 738.87}, {"w": "porque", "s": 738.87, "e": 739.17}, {"w": "salga", "s": 739.17, "e": 739.63}, {"w": "en", "s": 739.63, "e": 739.79}, {"w": "una", "s": 739.79, "e": 739.95}, {"w": "revista", "s": 739.95, "e": 740.39}, {"w": "importante.", "s": 740.39, "e": 740.99}]}, {"id": "c144", "start": 741.609, "end": 745.787, "text": "Vale si otro, en otro lugar, con otros aparatos, puede volver a verlo.", "words": [{"w": "Vale", "s": 741.57, "e": 741.83}, {"w": "si", "s": 741.83, "e": 742.05}, {"w": "otro,", "s": 742.05, "e": 742.31}, {"w": "en", "s": 742.59, "e": 742.69}, {"w": "otro", "s": 742.69, "e": 742.89}, {"w": "lugar,", "s": 742.89, "e": 743.23}, {"w": "con", "s": 743.47, "e": 743.55}, {"w": "otros", "s": 743.55, "e": 743.79}, {"w": "aparatos,", "s": 743.79, "e": 744.49}, {"w": "puede", "s": 744.69, "e": 744.79}, {"w": "volver", "s": 744.79, "e": 745.21}, {"w": "a", "s": 745.21, "e": 745.37}, {"w": "verlo.", "s": 745.37, "e": 745.75}]}, {"id": "c145", "start": 746.737, "end": 750.47, "text": "Victor Ninov anunció dos elementos que nadie más pudo ver.", "words": [{"w": "Victor", "s": 746.67, "e": 747.03}, {"w": "Ninov", "s": 747.03, "e": 747.59}, {"w": "anunció", "s": 747.59, "e": 748.17}, {"w": "dos", "s": 748.17, "e": 748.41}, {"w": "elementos", "s": 748.41, "e": 748.93}, {"w": "que", "s": 748.93, "e": 749.27}, {"w": "nadie", "s": 749.27, "e": 749.55}, {"w": "más", "s": 749.55, "e": 749.85}, {"w": "pudo", "s": 749.85, "e": 750.13}, {"w": "ver.", "s": 750.13, "e": 750.43}]}, {"id": "c146", "start": 750.89, "end": 754.094, "text": "Y la tabla periódica, al final, se completó sin él.", "words": [{"w": "Y", "s": 750.93, "e": 750.97}, {"w": "la", "s": 750.97, "e": 751.09}, {"w": "tabla", "s": 751.09, "e": 751.41}, {"w": "periódica,", "s": 751.41, "e": 752.13}, {"w": "al", "s": 752.27, "e": 752.43}, {"w": "final,", "s": 752.43, "e": 752.71}, {"w": "se", "s": 752.95, "e": 753.05}, {"w": "completó", "s": 753.05, "e": 753.57}, {"w": "sin", "s": 753.57, "e": 753.81}, {"w": "él.", "s": 753.81, "e": 754.03}]}, {"id": "outro", "start": 755.994, "end": 761.994}]};
